window.KITAB_MBCL_DATA["markus"] = {"edition":"MBCL","book":{"id":"markus","nameBn":"মার্ক","chapters":16},"contentSha256":"be4d9ebe6532bfd062b83623cad483a225ae560c3437c33890121ad6f5e5cd42","chapters":{"1":[{"heading":"হযরত ইয়াহিয়া (আঃ)-এর তবলিগ","v":1,"ve":1,"vl":"1","bn":"ইব্‌নুল্লাহ্‌ ঈসা মসীহের বিষয়ে সুসংবাদের শুরু।"},{"v":2,"ve":2,"vl":"2","bn":"নবী ইশাইয়ার কিতাবে আল্লাহ্‌র বলা এই কথা লেখা আছে: দেখ, তোমার আগে আমি আমার সংবাদদাতাকে পাঠাচ্ছি। সে তোমার পথ প্রস্তুত করবে।"},{"v":3,"ve":3,"vl":"3","bn":"মরুভূমিতে একজনের কণ্ঠস্বর চিৎকার করে জানাচ্ছে, তোমরা মাবুদের পথ ঠিক কর, তাঁর রাস্তা সোজা কর।"},{"v":4,"ve":4,"vl":"4","bn":"সেই কথামতই হযরত ইয়াহিয়া মরুভূমিতে গিয়ে লোকদের তরিকাবন্দী দিচ্ছিলেন এবং তবলিগ করছিলেন যেন লোকে গুনাহের মাফ পাবার জন্য তওবা করে ও তরিকাবন্দী নেয়।"},{"v":5,"ve":5,"vl":"5","bn":"তাতে এহুদিয়া প্রদেশ ও জেরুজালেম শহরের সবাই বের হয়ে ইয়াহিয়ার কাছে আসতে লাগল। তারা যখন গুনাহ্‌ স্বীকার করল তখন ইয়াহিয়া জর্ডান নদীতে তাদের তরিকাবন্দী দিলেন।"},{"v":6,"ve":6,"vl":"6","bn":"ইয়াহিয়া উটের লোমের কাপড় পরতেন এবং তাঁর কোমরে চামড়ার কোমর-বাঁধনি ছিল। তিনি পংগপাল আর বনমধু খেতেন।"},{"v":7,"ve":7,"vl":"7","bn":"তিনি যা তবলিগ করতেন তা এই, “আমার পরে একজন আসছেন। তিনি আমার চেয়ে শক্তিশালী। উবুড় হয়ে তাঁর জুতার ফিতা খুলবার যোগ্যও আমি নই।"},{"v":8,"ve":8,"vl":"8","bn":"আমি তোমাদের পানিতে তরিকাবন্দী দিচ্ছি কিন্তু তিনি পাক-রূহে তোমাদের তরিকাবন্দী দেবেন।”"},{"heading":"হযরত ঈসা মসীহের তরিকাবন্দী ও পরীক্ষা","v":9,"ve":9,"vl":"9","bn":"সেই সময়ে ঈসা গালীল প্রদেশের নাসরত গ্রাম থেকে আসলেন, আর ইয়াহিয়া তাঁকে জর্ডান নদীতে তরিকাবন্দী দিলেন।"},{"v":10,"ve":10,"vl":"10","bn":"পানি থেকে উঠে আসবার সংগে সংগেই ঈসা দেখলেন, আসমান চিরে গেছে এবং পাক-রূহ্‌ কবুতরের মত হয়ে তাঁর উপর নেমে আসছেন।"},{"v":11,"ve":11,"vl":"11","bn":"সেই সময় আসমান থেকে এই কথা শোনা গেল, “তুমিই আমার প্রিয় পুত্র, তোমার উপর আমি খুবই সন্তুষ্ট।”"},{"v":12,"ve":12,"vl":"12","bn":"এর পরেই ঈসাকে পাক-রূহের পরিচালনায় মরুভূমিতে যেতে হল।"},{"v":13,"ve":13,"vl":"13","bn":"সেই মরুভূমিতে চল্লিশ দিন ধরে শয়তান ঈসাকে লোভ দেখিয়ে গুনাহে ফেলবার চেষ্টা করতে লাগল। সেখানে অনেক বুনো জন্তু ছিল, আর ফেরেশতারা ঈসার সেবা করতেন।"},{"heading":"সাহাবী গ্রহণ","v":14,"ve":14,"vl":"14","bn":"ইয়াহিয়া জেলখানায় বন্দী হবার পরে ঈসা গালীল প্রদেশে গেলেন। সেখানে তিনি এই কথা বলে আল্লাহ্‌র দেওয়া সুসংবাদ তবলিগ করতে লাগলেন,"},{"v":15,"ve":15,"vl":"15","bn":"“সময় হয়েছে, আল্লাহ্‌র রাজ্য কাছে এসে গেছে। আপনারা তওবা করুন এবং এই সুসংবাদের উপর ঈমান আনুন।”"},{"v":16,"ve":16,"vl":"16","bn":"একদিন ঈসা গালীল সাগরের পার দিয়ে যাচ্ছিলেন। এমন সময় তিনি শিমোন ও তাঁর ভাই আন্দ্রিয়কে সাগরে জাল ফেলতে দেখলেন। সেই দু’জন ছিলেন জেলে।"},{"v":17,"ve":17,"vl":"17","bn":"ঈসা তাঁদের বললেন, “আমার সংগে চল। আমি তোমাদের মানুষ-ধরা জেলে করব।”"},{"v":18,"ve":18,"vl":"18","bn":"তখনই তাঁরা জাল ফেলে রেখে ঈসার সংগে গেলেন।"},{"v":19,"ve":19,"vl":"19","bn":"সেখান থেকে কিছু দূরে গেলে পর তিনি সিবদিয়ের দুই ছেলে ইয়াকুব ও ইউহোন্নাকে দেখতে পেলেন। তাঁরা তাঁদের নৌকায় বসে জাল ঠিক করছিলেন।"},{"v":20,"ve":20,"vl":"20","bn":"ঈসা তাঁদের দেখামাত্র ডাক দিলেন, আর তাঁরা তাঁদের বাবা সিবদিয়কে মজুরদের সংগে নৌকায় রেখে ঈসার সংগে গেলেন।"},{"heading":"ভূতে পাওয়া লোকটি","v":21,"ve":21,"vl":"21","bn":"ঈসা ও তাঁর সাহাবীরা কফরনাহূম শহরে গেলেন। পরে বিশ্রামবারে ঈসা মজলিস-খানায় গিয়ে শিক্ষা দিতে লাগলেন।"},{"v":22,"ve":22,"vl":"22","bn":"লোকেরা তাঁর শিক্ষায় আশ্চর্য হয়ে গেল, কারণ তিনি আলেমদের মত শিক্ষা দিচ্ছিলেন না বরং যাঁর অধিকার আছে সেই রকম লোকের মতই শিক্ষা দিচ্ছিলেন।"},{"v":23,"ve":23,"vl":"23","bn":"সেই সময় ভূতে পাওয়া একজন লোক সেই মজলিস-খানার মধ্যে ছিল।"},{"v":24,"ve":24,"vl":"24","bn":"সে চিৎকার করে বলল, “ওহে নাসরতের ঈসা, আমাদের সংগে আপনার কি দরকার? আপনি কি আমাদের সর্বনাশ করতে এসেছেন? আমি জানি আপনি কে; আপনিই তো আল্লাহ্‌র সেই পবিত্রজন।”"},{"v":25,"ve":25,"vl":"25","bn":"ঈসা তখন সেই ভূতকে ধমক দিয়ে বললেন, “চুপ কর, ওর মধ্য থেকে বের হয়ে যাও।”"},{"v":26,"ve":26,"vl":"26","bn":"সেই ভূত তখন লোকটাকে মুচ্‌ড়ে ধরল এবং জোরে চিৎকার করে তার মধ্য থেকে বের হয়ে গেল।"},{"v":27,"ve":27,"vl":"27","bn":"এই ঘটনা দেখে লোকেরা এমন আশ্চর্য হল যে, তারা নিজেদের মধ্যে বলতে লাগল, “এই সব কি ব্যাপার? এই অধিকার-ভরা নতুন শিক্ষাই বা কি? এমন কি, ভূতদেরও তিনি হুকুম দেন আর তারা তাঁর কথা শুনতে বাধ্য হয়।”"},{"v":28,"ve":28,"vl":"28","bn":"এতে গালীল প্রদেশের সব জায়গায় ঈসার কথা খুব তাড়াতাড়ি ছড়িয়ে পড়ল।"},{"heading":"অনেকে সুস্থ হল","v":29,"ve":29,"vl":"29","bn":"পরে তাঁরা মজলিস-খানা থেকে বের হয়ে শিমোন ও আন্দ্রিয়ের বাড়ীতে গেলেন। ইয়াকুব এবং ইউহোন্নাও তাঁদের সংগে ছিলেন।"},{"v":30,"ve":30,"vl":"30","bn":"শিমোনের শাশুড়ীর জ্বর হয়েছিল বলে তিনি শুয়ে ছিলেন। ঈসা আসামাত্রই তাঁর কথা তাঁকে বলা হল।"},{"v":31,"ve":31,"vl":"31","bn":"তখন ঈসা তাঁর কাছে গিয়ে হাত ধরে তাঁকে তুললেন। তাতে তাঁর জ্বর ছেড়ে গেল এবং তিনি তাঁদের খাওয়া-দাওয়ার ব্যবস্থা করতে লাগলেন।"},{"v":32,"ve":32,"vl":"32","bn":"সেই দিন সূর্য ডুবে গেলে পর সন্ধ্যাবেলা লোকেরা সব রোগীদের ও ভূতে পাওয়া লোকদের ঈসার কাছে আনল।"},{"v":33,"ve":33,"vl":"33","bn":"শহরের সব লোক তখন সেই বাড়ীর দরজার কাছে এসে জমায়েত হল।"},{"v":34,"ve":34,"vl":"34","bn":"ঈসা অনেক রকমের রোগীকে সুস্থ করলেন এবং অনেক ভূত ছাড়ালেন। তিনি ভূতদের কথা বলতে দিলেন না, কারণ সেই ভূতেরা জানত তিনি কে।"},{"heading":"গালীল প্রদেশে তবলিগ","v":35,"ve":35,"vl":"35","bn":"পরদিন খুব ভোরে অন্ধকার থাকতেই ঈসা উঠলেন এবং ঘর ছেড়ে একটা নির্জন জায়গায় গিয়ে মুনাজাত করতে লাগলেন।"},{"v":36,"ve":36,"vl":"36","bn":"শিমোন ও তাঁর সংগীরা ঈসাকে তালাশ করছিলেন।"},{"v":37,"ve":37,"vl":"37","bn":"পরে তাঁকে তালাশ করে পেয়ে বললেন, “সবাই আপনাকে তালাশ করছে।”"},{"v":38,"ve":38,"vl":"38","bn":"ঈসা তাঁদের বললেন, “চল, আমরা কাছের গ্রামগুলোতে যাই যেন আমি সেখানেও তবলিগ করতে পারি, কারণ সেইজন্যই তো আমি এসেছি।”"},{"v":39,"ve":39,"vl":"39","bn":"এইভাবে ঈসা গালীলের সব জায়গায় গিয়ে ইহুদীদের মজলিস-খানাগুলোতে তবলিগ করলেন এবং ভূত দূর করলেন।"},{"heading":"একজন চর্মরোগী সুস্থ হল","v":40,"ve":40,"vl":"40","bn":"পরে একজন চর্মরোগী ঈসার কাছে এসে তাঁর সামনে হাঁটু পেতে বলল, “আপনি ইচ্ছা করলেই আমাকে ভাল করতে পারেন।”"},{"v":41,"ve":41,"vl":"41","bn":"লোকটির উপর ঈসার খুব মমতা হল। তিনি হাত বাড়িয়ে তাকে ছুঁয়ে বললেন, “আমি তা-ই চাই, তুমি পাক-সাফ হও।”"},{"v":42,"ve":42,"vl":"42","bn":"আর তখনই তার চর্মরোগ ভাল হয়ে গেল।"},{"v":43,"ve":43,"vl":"43","bn":"ঈসা তখনই তাকে বিদায় করলেন, কিন্তু তার আগে তাকে কড়াকড়িভাবে বললেন,"},{"v":44,"ve":44,"vl":"44","bn":"“দেখ, এই কথা কাউকে বোলো না। তুমি বরং ইমামের কাছে গিয়ে নিজেকে দেখাও আর পাক-সাফ হবার জন্য মূসা যে কোরবানীর হুকুম দিয়েছেন তা কোরবানী দাও। এতে ইমামদের কাছে প্রমাণ হবে যে, তুমি ভাল হয়েছ।”"},{"v":45,"ve":45,"vl":"45","bn":"সেই লোকটি কিন্তু বাইরে গিয়ে সব জায়গায় এই খবর ছড়াতে লাগল। তার ফলে ঈসা কোন গ্রামে আর খোলাখুলিভাবে যেতে পারলেন না। তাঁকে নির্জন জায়গায় থাকতে হল; তবুও লোকেরা সব জায়গা থেকে তাঁর কাছে আসতে লাগল।"}],"2":[{"heading":"অবশ-রোগী সুস্থ হল","v":1,"ve":1,"vl":"1","bn":"কয়েকদিন পরে ঈসা আবার কফরনাহূমে গেলেন। লোকেরা শুনল তিনি ঘরে আছেন।"},{"v":2,"ve":2,"vl":"2","bn":"তখন এত লোক সেখানে জমায়েত হল যে, ঘর তো দূরের কথা, দরজার বাইরেও আর জায়গা রইল না। ঈসা লোকদের কাছে আল্লাহ্‌র কালাম তবলিগ করছিলেন।"},{"v":3,"ve":3,"vl":"3","bn":"এমন সময় কয়েকজন লোক একজন অবশ-রোগীকে তাঁর কাছে নিয়ে আসল। চারজন লোক তাকে বয়ে আনছিল,"},{"v":4,"ve":4,"vl":"4","bn":"কিন্তু ভিড়ের জন্য তারা তাকে ঈসার কাছে নিয়ে যেতে পারল না। এইজন্য ঈসা যেখানে ছিলেন ঠিক তার উপরের ছাদের কিছু অংশ তারা সরিয়ে ফেলল। তারপর সেই খোলা জায়গা দিয়ে মাদুর সুদ্ধই সেই অবশ-রোগীকে নীচে নামিয়ে দিল।"},{"v":5,"ve":5,"vl":"5","bn":"তারা ঈমান এনেছে দেখে ঈসা সেই অবশ-রোগীকে বললেন, “বাছা, তোমার গুনাহ্‌ মাফ করা হল।”"},{"v":6,"ve":6,"vl":"6","bn":"সেখানে কয়েকজন আলেম বসে ছিলেন। তাঁরা মনে মনে ভাবছিলেন,"},{"v":7,"ve":7,"vl":"7","bn":"“লোকটা এই রকম কথা বলছে কেন? সে তো কুফরী করছে। একমাত্র আল্লাহ্‌ ছাড়া আর কে গুনাহ্‌ মাফ করতে পারে?”"},{"v":8,"ve":8,"vl":"8","bn":"তাঁরা যে ঐ সব কথা ভাবছেন তা ঈসা নিজের অন্তরে তখনই বুঝতে পারলেন। এইজন্য তিনি তাঁদের বললেন, “আপনারা কেন মনে মনে ঐ সব কথা ভাবছেন?"},{"v":9,"ve":9,"vl":"9","bn":"এই অবশ-রোগীকে কোন্‌টা বলা সহজ- ‘তোমার গুনাহ্‌ মাফ করা হল,’ না, ‘ওঠো, তোমার মাদুর তুলে নিয়ে হেঁটে বেড়াও’?"},{"v":10,"ve":10,"vl":"10","bn":"কিন্তু আপনারা যেন জানতে পারেন দুনিয়াতে গুনাহ্‌ মাফ করবার ক্ষমতা ইব্‌ন্তেআদমের আছে”- এই পর্যন্ত বলে তিনি সেই অবশ-রোগীকে বললেন,"},{"v":11,"ve":11,"vl":"11","bn":"“আমি তোমাকে বলছি, ওঠো, তোমার মাদুর তুলে নিয়ে বাড়ী চলে যাও।”"},{"v":12,"ve":12,"vl":"12","bn":"তখনই সেই লোকটি উঠে তার মাদুর তুলে নিল এবং সকলের সামনেই বাইরে চলে গেল। এতে সবাই আশ্চর্য হয়ে আল্লাহ্‌র প্রশংসা করে বলল, “আমরা কখনও এই রকম দেখি নি।”"},{"heading":"হযরত লেবির প্রতি হযরত ঈসা মসীহের ডাক","v":13,"ve":13,"vl":"13","bn":"পরে ঈসা আবার গালীল সাগরের ধারে গেলেন। তখন অনেক লোক তাঁর কাছে আসল, আর তিনি তাদের শিক্ষা দিতে লাগলেন।"},{"v":14,"ve":14,"vl":"14","bn":"এর পরে তিনি পথে যেতে যেতে দেখলেন আল্‌ফেয়ের ছেলে লেবি খাজনা আদায় করবার ঘরে বসে আছেন। ঈসা তাঁকে বললেন, “এস, আমার উম্মত হও।” তখন লেবি উঠে ঈসার সংগে গেলেন।"},{"v":15,"ve":15,"vl":"15","bn":"পরে ঈসা লেবির বাড়ীতে খেতে বসলেন। তখন অনেক খাজনা-আদায়কারী ও খারাপ লোকেরাও ঈসা ও তাঁর সাহাবীদের সংগে খেতে বসল, কারণ অনেক লোক ঈসার সংগে সংগে যাচ্ছিল।"},{"v":16,"ve":16,"vl":"16","bn":"ফরীশী দলের আলেমেরা যখন দেখলেন ঈসা খাজনা-আদায়কারী ও খারাপ লোকদের সংগে খাচ্ছেন তখন তাঁরা তাঁর সাহাবীদের বললেন, “উনি খাজনা-আদায়কারী ও খারাপ লোকদের সংগে খাওয়া-দাওয়া করেন কেন?”"},{"v":17,"ve":17,"vl":"17","bn":"এই কথা শুনে ঈসা সেই আলেমদের বললেন, “সুস্থদের জন্য ডাক্তারের দরকার নেই বরং অসুস্থদের জন্যই দরকার আছে। আমি ধার্মিকদের ডাকতে আসি নি বরং গুনাহ্‌গারদেরই ডাকতে এসেছি।”"},{"heading":"রোজার বিষয়ে শিক্ষা","v":18,"ve":18,"vl":"18","bn":"একবার ইয়াহিয়ার সাহাবীরা ও ফরীশীরা রোজা রাখছিলেন। তা দেখে কয়েকজন লোক ঈসার কাছে এসে বলল, “ইয়াহিয়ার সাহাবীরা ও ফরীশীদের শাগরেদেরা রোজা রাখেন, কিন্তু আপনার সাহাবীরা রাখেন না কেন?”"},{"v":19,"ve":19,"vl":"19","bn":"ঈসা তাদের বললেন, “বর সংগে থাকতে কি বরের সংগের লোকেরা রোজা রাখতে পারে? যতদিন বর সংগে থাকে ততদিন তারা রোজা রাখতে পারে না।"},{"v":20,"ve":20,"vl":"20","bn":"কিন্তু সময় আসছে যখন তাদের কাছ থেকে বরকে নিয়ে যাওয়া হবে, আর সেই সময় তারা রোজা রাখবে।"},{"v":21,"ve":21,"vl":"21","bn":"“কেউ পুরানো কোর্তায় নতুন কাপড়ের তালি দেয় না। যদি দেয় তবে সেই পুরানো কাপড় থেকে নতুন তালিটা ছিঁড়ে আসে। তাতে সেই ছেঁড়া আরও বড় হয়।"},{"v":22,"ve":22,"vl":"22","bn":"পুরানো চামড়ার থলিতে কেউ টাটকা আংগুর-রস রাখে না। যদি রাখে তবে টাটকা রসের দরুন থলি ফেটে গিয়ে রস ও থলি দু’টাই নষ্ট হয়। টাটকা রস নতুন থলিতেই রাখা হয়।”"},{"heading":"বিশ্রামবার সম্বন্ধে শিক্ষা","v":23,"ve":23,"vl":"23","bn":"এক বিশ্রামবারে ঈসা শস্যক্ষেতের মধ্য দিয়ে যাচ্ছিলেন। তাঁর সাহাবীরা যেতে যেতে শীষ ছিঁড়তে লাগলেন।"},{"v":24,"ve":24,"vl":"24","bn":"তাতে ফরীশীরা ঈসাকে বললেন, “শরীয়ত মতে বিশ্রামবারে যা করা উচিত নয় তা ওরা করছে কেন?”"},{"v":25,"ve":26,"vl":"25-26","bn":"ঈসা তাঁদের বললেন, “অবিয়াথর যখন মহা-ইমাম ছিলেন সেই সময় দাউদ ও তাঁর সংগীদের একবার খিদে পেয়েছিল, কিন্তু তাঁদের সংগে কোন খাবার ছিল না। তখন দাউদ যা করেছিলেন তা কি আপনারা কখনও পড়েন নি? তিনি তো আল্লাহ্‌র ঘরে ঢুকে পবিত্র-রুটি খেয়েছিলেন এবং সংগীদেরও তা দিয়েছিলেন। কিন্তু এই রুটি ইমামেরা ছাড়া আর কারও খাবার নিয়ম ছিল না।”"},{"v":27,"ve":27,"vl":"27","bn":"ঈসা তাঁদের আরও বললেন, “মানুষের জন্যই বিশ্রামবারের সৃষ্টি হয়েছে, কিন্তু বিশ্রামবারের জন্য মানুষের সৃষ্টি হয় নি।"},{"v":28,"ve":28,"vl":"28","bn":"তাই ইব্‌ন্তেআদম বিশ্রামবারেরও মালিক।”"}],"3":[{"heading":"শুকনা-হাত লোকটি সুস্থ হল","v":1,"ve":1,"vl":"1","bn":"এর পরে ঈসা আবার মজলিস-খানায় গেলেন। সেখানে একজন লোক ছিল যার একটা হাত শুকিয়ে গিয়েছিল।"},{"v":2,"ve":2,"vl":"2","bn":"ফরীশীদের মধ্যে কয়েকজন ঈসাকে দোষ দেবার অজুহাত খুঁজছিলেন। বিশ্রামবারে ঈসা লোকটাকে সুস্থ করেন কি না তা দেখবার জন্য তাঁরা তাঁর উপর ভাল করে নজর রাখতে লাগলেন।"},{"v":3,"ve":3,"vl":"3","bn":"ঈসা সেই শুকনা-হাত লোকটিকে বললেন, “সকলের সামনে এসে দাঁড়াও।”"},{"v":4,"ve":4,"vl":"4","bn":"তারপর ঈসা ফরীশীদের জিজ্ঞাসা করলেন, “বিশ্রামবারে ভাল কাজ করা উচিত, না খারাপ কাজ করা উচিত? প্রাণ রক্ষা করা উচিত, না নষ্ট করা উচিত?” ফরীশীরা কিন্তু কোনই জবাব দিলেন না।"},{"v":5,"ve":5,"vl":"5","bn":"তখন ঈসা বিরক্ত হয়ে তাঁদের দিকে তাকিয়ে দেখলেন এবং তাঁদের অন্তরের কঠিনতার জন্য গভীর দুঃখের সংগে সেই লোকটিকে বললেন, “তোমার হাত বাড়িয়ে দাও।” লোকটি হাত বাড়িয়ে দিলে পর তার হাত একেবারে ভাল হয়ে গেল।"},{"v":6,"ve":6,"vl":"6","bn":"তখন ফরীশীরা বাইরে গেলেন এবং কিভাবে ঈসাকে হত্যা করা যায় সেই বিষয়ে বাদশাহ্‌ হেরোদের দলের লোকদের সংগে পরামর্শ করতে লাগলেন।"},{"heading":"হযরত ঈসা মসীহের পিছনে পিছনে লোকেরা","v":7,"ve":8,"vl":"7-8","bn":"এর পরে ঈসা তাঁর সাহাবীদের সংগে সাগরের ধারে গেলেন। গালীল প্রদেশের অনেক লোক তাঁর পিছনে পিছনে চলল। ঈসা যে সব কাজ করছিলেন সেগুলোর কথা শুনে এহুদিয়া, জেরুজালেম, ইদোম, জর্ডান নদীর ওপার এবং টায়ার ও সিডন শহরের চারদিক থেকে অনেক লোক তাঁর কাছে আসল।"},{"v":9,"ve":9,"vl":"9","bn":"ঈসা নিজের জন্য একটা ছোট নৌকা তাঁর সাহাবীদের ঠিক করে রাখতে বললেন যেন ভিড়ের দরুন লোকে চাপাচাপি করে তাঁর উপর না পড়ে।"},{"v":10,"ve":10,"vl":"10","bn":"তিনি অনেক লোককে সুস্থ করেছিলেন বলে রোগীরা তাঁকে ছোঁবার জন্য ঠেলাঠেলি করছিল।"},{"v":11,"ve":11,"vl":"11","bn":"ভূতেরা যখনই তাঁকে দেখত তখনই তাঁর সামনে মাটিতে পড়ে চিৎকার করে বলত, “আপনিই ইব্‌নুল্লাহ্‌।”"},{"v":12,"ve":12,"vl":"12","bn":"কিন্তু তিনি খুব কড়াভাবে তাদের হুকুম দিতেন যেন তারা কাউকে না বলে তিনি কে।"},{"heading":"বারোজন সাহাবীকে সাহাবী-পদ দান","v":13,"ve":15,"vl":"13-15","bn":"এর পরে ঈসা পাহাড়ের উপরে উঠলেন এবং নিজের ইচ্ছামত কিছু লোককে তাঁর কাছে ডেকে নিলেন। তাঁরা ঈসার কাছে আসলে পর তিনি বারোজনকে সাহাবী-পদে নিযুক্ত করলেন যেন তাঁরা তাঁর সংগে সংগে থাকেন এবং ভূত ছাড়াবার ক্ষমতা দিয়ে তিনি তাঁদের তবলিগ-কাজে পাঠাতে পারেন।"},{"v":16,"ve":16,"vl":"16","bn":"যে বারোজনকে তিনি নিযুক্ত করেছিলেন তাঁরা হলেন শিমোন, যাঁর নাম তিনি দিলেন পিতর;"},{"v":17,"ve":17,"vl":"17","bn":"সিবদিয়ের দুই ছেলে ইয়াকুব ও ইউহোন্না (এঁদের নাম তিনি দিলেন বোয়ানের্গিস, অর্থাৎ বজ্রধ্বনির পুত্রেরা);"},{"v":18,"ve":18,"vl":"18","bn":"আন্দ্রিয়, ফিলিপ, বর্‌থলময়, মথি, থোমা, আলফেয়ের ছেলে ইয়াকুব, থদ্দেয়, মৌলবাদী শিমোন,"},{"v":19,"ve":19,"vl":"19","bn":"আর এহুদা ইষ্কারিয়োৎ, যে ঈসাকে শত্রুদের হাতে ধরিয়ে দিয়েছিল।"},{"heading":"হযরত ঈসা মসীহ্‌ ও ভূতদের বাদশাহ্‌","v":20,"ve":20,"vl":"20","bn":"ঈসা ঘরে আসলে পর আবার এত লোক তাঁর কাছে জমায়েত হল যে, তিনি ও তাঁর সাহাবীরা কিছু খেতেও পারলেন না।"},{"v":21,"ve":21,"vl":"21","bn":"ঈসার নিজের লোকেরা এই খবর শুনে তাঁকে বের করে নিতে আসলেন। তাঁরা বললেন, “ও পাগল হয়ে গেছে।”"},{"v":22,"ve":22,"vl":"22","bn":"জেরুজালেম থেকে যে আলেমেরা এসেছিলেন তাঁরা বললেন, “ওকে বেল্‌সবূলে পেয়েছে। ভূতদের বাদশাহ্‌র সাহায্যেই ও ভূত ছাড়ায়।”"},{"v":23,"ve":23,"vl":"23","bn":"ঈসা সেই আলেমদের ডাকলেন এবং শিক্ষা দেবার জন্য বললেন, “শয়তান কেমন করে শয়তানকে তাড়িয়ে দিতে পারে?"},{"v":24,"ve":24,"vl":"24","bn":"কোন রাজ্য নিজের মধ্যে ভাগ হয়ে গেলে সেই রাজ্য টিকতে পারে না।"},{"v":25,"ve":25,"vl":"25","bn":"আবার কোন পরিবার যদি ভাগ হয়ে যায় তবে সেই পরিবারও টিকতে পারে না।"},{"v":26,"ve":26,"vl":"26","bn":"সেইভাবে শয়তানও যদি নিজের বিরুদ্ধে দাঁড়িয়ে তাঁর শক্তিতে ভাংগন ধরায় তবে সেও টিকতে পারে না এবং সেখানেই তার শেষ হয়।"},{"v":27,"ve":27,"vl":"27","bn":"এই কথা ঠিক যে, একজন বলবান লোককে প্রথমে বেঁধে না রেখে তার ঘরে ঢুকে তার জিনিসপত্র কেউই নিয়ে যেতে পারে না। তাকে বাঁধলে পরে তবেই সে তার ঘর লুট করতে পারবে।"},{"v":28,"ve":28,"vl":"28","bn":"আমি আপনাদের সত্যি বলছি, মানুষের সমস্ত গুনাহ্‌ এবং কুফরী মাফ করা হবে,"},{"v":29,"ve":29,"vl":"29","bn":"কিন্তু পাক-রূহের বিরুদ্ধে কুফরী কখনও মাফ করা হবে না। সেই লোকের গুনাহ্‌ চিরকাল থাকবে।”"},{"v":30,"ve":30,"vl":"30","bn":"আলেমেরা যে বলেছিলেন, “ওকে ভূতে পেয়েছে,” তাঁদের সেই কথার জন্যই ঈসা এই সব বললেন।"},{"v":31,"ve":31,"vl":"31","bn":"এর পরে ঈসার মা ও ভাইয়েরা সেখানে আসলেন এবং বাইরে দাঁড়িয়ে থেকে তাঁকে ডেকে পাঠালেন।"},{"v":32,"ve":32,"vl":"32","bn":"ঈসার চারদিকে তখন অনেক লোক বসে ছিল। তারা তাঁকে বলল, “আপনার মা ও ভাইয়েরা বাইরে আপনার খোঁজ করছেন।”"},{"v":33,"ve":33,"vl":"33","bn":"ঈসা বললেন, “কে আমার মা, আর কারা আমার ভাই?”"},{"v":34,"ve":34,"vl":"34","bn":"যারা তাঁকে ঘিরে বসে ছিল তিনি তাদের দিকে তাকিয়ে বললেন, “এই তো আমার মা ও ভাইয়েরা!"},{"v":35,"ve":35,"vl":"35","bn":"আল্লাহ্‌র ইচ্ছা যারা পালন করে তারাই আমার ভাই, বোন ও মা।”"}],"4":[{"heading":"একজন চাষীর গল্প","v":1,"ve":1,"vl":"1","bn":"ঈসা আবার গালীল সাগরের ধারে লোকদের শিক্ষা দিতে লাগলেন। তাঁর চারদিকে অনেক লোকের ভিড় হল; সেইজন্য তিনি সাগরের মধ্যে একটা নৌকায় উঠে বসলেন আর লোকেরা সাগরের ধারে দাঁড়িয়ে রইল।"},{"v":2,"ve":2,"vl":"2","bn":"তিনি গল্পের মধ্য দিয়ে অনেক বিষয় তাদের শিক্ষা দিতে লাগলেন। তার মধ্যে তিনি বললেন,"},{"v":3,"ve":3,"vl":"3","bn":"“শুনুন, একজন চাষী বীজ বুনতে গেল।"},{"v":4,"ve":4,"vl":"4","bn":"বীজ বুনবার সময় কতগুলো বীজ পথের পাশে পড়ল, আর পাখীরা এসে তা খেয়ে ফেলল।"},{"v":5,"ve":5,"vl":"5","bn":"আবার কতগুলো বীজ পাথুরে জমিতে পড়ল। সেখানে বেশী মাটি ছিল না। মাটি গভীর ছিল না বলে তাড়াতাড়ি চারা গজিয়ে উঠল।"},{"v":6,"ve":6,"vl":"6","bn":"সূর্য উঠলে পর সেগুলো পুড়ে গেল এবং শিকড় ভাল করে বসে নি বলে শুকিয়ে গেল।"},{"v":7,"ve":7,"vl":"7","bn":"আর কতগুলো বীজ কাঁটাবনের মধ্যে পড়ল। কাঁটাগাছ বেড়ে উঠে চারাগুলো চেপে রাখল, তাই ফল ধরল না।"},{"v":8,"ve":8,"vl":"8","bn":"কিন্তু আর কতগুলো বীজ ভাল জমিতে পড়ল এবং গাছ বের হয়ে বেড়ে উঠল ও ফল দিল; কোনটাতে ত্রিশ গুণ, কোনটাতে ষাট গুণ, আবার কোনটাতে একশোগুণ ফসল জন্মাল।”"},{"v":9,"ve":9,"vl":"9","bn":"শেষে ঈসা বললেন, “যার শুনবার কান আছে, সে শুনুক।”"},{"heading":"গল্প বলবার উদ্দেশ্য","v":10,"ve":10,"vl":"10","bn":"ভিড় কমে গেলে পর ঈসার চারপাশের লোকেরা আর তাঁর বারোজন সাহাবী সেই গল্পের বিষয় তাঁকে জিজ্ঞাসা করলেন।"},{"v":11,"ve":11,"vl":"11","bn":"ঈসা তাঁদের বললেন, “আল্লাহ্‌র রাজ্যের গোপন সত্য তোমাদেরই জানতে দেওয়া হয়েছে, কিন্তু অন্যদের কাছে গল্পের মধ্য দিয়ে সব কথা বলা হয়,"},{"v":12,"ve":12,"vl":"12","bn":"যেন পাক-কিতাবের কথামত, ‘তারা তাকিয়েও দেখতে না পায় এবং শুনেও বুঝতে না পারে। তা না হলে তারা হয়তো আল্লাহ্‌র দিকে ফিরবে এবং মাফ পাবে।’ ”"},{"heading":"চাষীর গল্পের অর্থ","v":13,"ve":13,"vl":"13","bn":"তারপর ঈসা তাঁদের বললেন, “তোমরা কি এই গল্পটার মানে বুঝলে না? তাহলে কেমন করে অন্য গল্পগুলোর মানে বুঝবে?"},{"v":14,"ve":14,"vl":"14","bn":"চাষী যে বীজ বুনেছিল তা হল আল্লাহ্‌র কালাম।"},{"v":15,"ve":15,"vl":"15","bn":"পথের পাশে পড়া বীজের মধ্য দিয়ে তাদের সম্বন্ধেই বলা হয়েছে যারা সেই কালাম শোনে, কিন্তু শয়তান তখনই এসে তাদের অন্তরে যে কালাম বোনা হয়েছিল তা নিয়ে যায়।"},{"v":16,"ve":16,"vl":"16","bn":"পাথুরে জমিতে পড়া বীজের মধ্য দিয়ে তাদের সম্বন্ধেই বলা হয়েছে যারা সেই কালাম শুনে তখনই আনন্দের সংগে তা গ্রহণ করে,"},{"v":17,"ve":17,"vl":"17","bn":"কিন্তু তাদের মধ্যে শিকড় ভাল করে বসে না বলে কেবল অল্প দিনের জন্য তারা স্থির থাকে। পরে কালামের জন্য যখন কষ্ট এবং জুলুম আসে তখনই তারা পিছিয়ে যায়।"},{"v":18,"ve":18,"vl":"18","bn":"আবার কাঁটাবনের মধ্যে বোনা বীজের মধ্য দিয়ে তাদের সম্বন্ধেই বলা হয়েছে যারা সেই কালাম শোনে,"},{"v":19,"ve":19,"vl":"19","bn":"কিন্তু সংসারের চিন্তা-ভাবনা, ধন-সম্পত্তির মায়া এবং অন্যান্য জিনিসের লোভ এসে সেই কালামকে চেপে রাখে;"},{"v":20,"ve":20,"vl":"20","bn":"সেইজন্য তাতে কোন ফল হয় না। আর ভাল জমিতে বোনা বীজের মধ্য দিয়ে তাদের সম্বন্ধে বলা হয়েছে যারা সেই কালাম শুনে তা গ্রহণ করে এবং ফল দেয়। কেউ দেয় ত্রিশগুণ, কেউ দেয় ষাট গুণ আবার কেউ দেয় একশো গুণ।”"},{"v":21,"ve":21,"vl":"21","bn":"ঈসা আরও বললেন, “কেউ কি বাতি নিয়ে ঝুড়ি বা খাটের নীচে রাখে? সে কি তা বাতিদানের উপর রাখে না?"},{"v":22,"ve":22,"vl":"22","bn":"কোন জিনিস যদি লুকানো থাকে তবে তা প্রকাশিত হবার জন্যই লুকানো থাকে; আবার কোন জিনিস যদি ঢাকা থাকে তবে তা খুলবার জন্যই ঢাকা থাকে।"},{"v":23,"ve":23,"vl":"23","bn":"যদি কারও শুনবার কান থাকে সে শুনুক।”"},{"v":24,"ve":24,"vl":"24","bn":"এর পরে ঈসা বললেন, “তোমরা যা শুনছ সেই বিষয়ে মনোযোগ দাও। তোমরা যেভাবে মেপে দাও তোমাদের জন্য সেইভাবে মাপা হবে; এমন কি, বেশী করেই মাপা হবে।"},{"v":25,"ve":25,"vl":"25","bn":"যার আছে তাকে আরও দেওয়া হবে, কিন্তু যার নেই তার যা আছে তা-ও তার কাছ থেকে নিয়ে নেওয়া হবে।”"},{"heading":"ফসলের গল্প","v":26,"ve":26,"vl":"26","bn":"ঈসা আরও বললেন, “আল্লাহ্‌র রাজ্য এই রকম: একজন লোক জমিতে বীজ ছড়াল।"},{"v":27,"ve":27,"vl":"27","bn":"পরে সে রাতে ঘুমিয়ে ও দিনে জেগে থেকে সময় কাটাল। এর মধ্যে সেই বীজ থেকে চারা গজিয়ে বড় হল, কিন্তু কিভাবে হল তা সে জানল না।"},{"v":28,"ve":28,"vl":"28","bn":"জমি নিজে নিজেই ফল জন্মাল- প্রথমে চারা, পরে শীষ এবং শীষের মাথায় পরিপূর্ণ শস্যের দানা।"},{"v":29,"ve":29,"vl":"29","bn":"দানা পাকলে পর সে কাসে- লাগাল, কারণ ফসল কাটবার সময় হয়েছে।”"},{"heading":"সরিষা দানার গল্প","v":30,"ve":30,"vl":"30","bn":"তারপর ঈসা বললেন, “কিসের সংগে আমরা আল্লাহ্‌র রাজ্যের তুলনা করব? কোন্‌ দৃষ্টান্তের মধ্য দিয়ে তা বুঝাব?"},{"v":31,"ve":31,"vl":"31","bn":"সেই রাজ্য একটা সরিষা দানার মত। জমিতে বুনবার সময় দেখা যায় যে, ওটা সব বীজের মধ্যে সবচেয়ে ছোট।"},{"v":32,"ve":32,"vl":"32","bn":"কিন্তু লাগাবার পর যখন গাছ বেড়ে ওঠে তখন সমস্ত শাক-সব্‌জির মধ্যে ওটা সবচেয়ে বড় হয়, আর এমন বড় বড় ডাল বের হয় যে, পাখীরাও তার আড়ালে বাসা বাঁধে।”"},{"v":33,"ve":33,"vl":"33","bn":"এই রকম আরও অনেক গল্পের মধ্য দিয়ে ঈসা আল্লাহ্‌র কালাম লোকদের কাছে বলতেন। তারা যতটুকু বুঝতে পারত ততটুকুই তিনি তাদের কাছে বলতেন।"},{"v":34,"ve":34,"vl":"34","bn":"গল্প ছাড়া তিনি তাদের শিক্ষা দিতেন না, কিন্তু সাহাবীরা যখন তাঁর সংগে একা থাকতেন তখন তিনি সব কিছু তাঁদের বুঝিয়ে দিতেন।"},{"heading":"ঝড় থামানো","v":35,"ve":35,"vl":"35","bn":"সেই দিন সন্ধ্যাবেলা ঈসা তাঁর সাহাবীদের বললেন, “চল, আমরা সাগরের ওপারে যাই।”"},{"v":36,"ve":36,"vl":"36","bn":"তখন সাহাবীরা লোকদের ছেড়ে ঈসা যে নৌকায় ছিলেন সেই নৌকাতে করে তাঁকে নিয়ে চললেন। অবশ্য সেখানে আরও অন্য নৌকাও ছিল।"},{"v":37,"ve":37,"vl":"37","bn":"নৌকা যখন চলছিল তখন একটা ভীষণ ঝড় উঠল এবং ঢেউগুলো নৌকার উপর এমনভাবে আছড়ে পড়ল যে, নৌকা পানিতে ভরে উঠতে লাগল।"},{"v":38,"ve":38,"vl":"38","bn":"ঈসা কিন্তু নৌকার পিছন দিকে একটা বালিশের উপর মাথা রেখে ঘুমাচ্ছিলেন। সাহাবীরা তাঁকে জাগিয়ে বললেন, “হুজুর, আমরা যে মারা পড়ছি সেদিকে কি আপনার খেয়াল নেই?”"},{"v":39,"ve":39,"vl":"39","bn":"ঈসা উঠে বাতাসকে ধমক দিলেন এবং সাগরকে বললেন, “থাম, শান্ত হও।” তাতে বাতাস থেমে গেল ও সব কিছু খুব শান্ত হয়ে গেল।"},{"v":40,"ve":40,"vl":"40","bn":"তিনি সাহাবীদের বললেন, “তোমরা ভয় পাও কেন? এখনও কি তোমাদের বিশ্বাস হয় নি?”"},{"v":41,"ve":41,"vl":"41","bn":"এতে সাহাবীরা ভীষণ ভয় পেলেন এবং নিজেদের মধ্যে বলাবলি করতে লাগলেন, “ইনি কে যে, বাতাস এবং সাগরও তাঁর কথা শোনে?”"}],"5":[{"heading":"ভূতে পাওয়া লোকটি","v":1,"ve":1,"vl":"1","bn":"তারপর ঈসা ও তাঁর সাহাবীরা গালীল সাগর পার হয়ে গেরাসেনীদের এলাকায় গেলেন।"},{"v":2,"ve":2,"vl":"2","bn":"ঈসা নৌকা থেকে নামতেই ভূতে পাওয়া একজন লোক কবরস্থান থেকে বের হয়ে তাঁর সামনে আসল।"},{"v":3,"ve":3,"vl":"3","bn":"লোকটা কবরস্থানেই থাকত এবং শিকল দিয়েও কেউ আর তাকে বেঁধে রাখতে পারত না।"},{"v":4,"ve":4,"vl":"4","bn":"তার হাত-পা প্রায়ই শিকল দিয়ে বাঁধা হত, কিন্তু সে শিকল ছিঁড়ে ফেলত এবং পায়ের বেড়ী ভেংগে ফেলত। কেউই তাকে সামলাতে পারত না।"},{"v":5,"ve":5,"vl":"5","bn":"সে দিনরাত কবরে কবরে ও পাহাড়ে পাহাড়ে চিৎকার করে বেড়াত এবং পাথর দিয়ে নিজেই নিজের শরীর কাটত।"},{"v":6,"ve":7,"vl":"6-7","bn":"ঈসাকে দূর থেকে দেখে সে দৌড়ে এসে তাঁর পায়ের উপর উবুড় হয়ে পড়ল, আর সে চিৎকার করে বলল, “আল্লাহ্‌তা’লার পুত্র ঈসা, আমার সংগে আপনার কি দরকার? আমি আপনাকে আল্লাহ্‌র কসম দিয়ে বলছি, আপনি আমাকে যন্ত্রণা দেবেন না।”"},{"v":8,"ve":8,"vl":"8","bn":"সে এই কথা বলল কারণ ঈসা তাকে বলেছিলেন, “ভূত, এই লোকটির মধ্য থেকে বের হয়ে যাও।”"},{"v":9,"ve":9,"vl":"9","bn":"ঈসা তাকে জিজ্ঞাসা করলেন, “তোমার নাম কি?” সে বলল, “আমার নাম বাহিনী, কারণ আমরা অনেকে আছি।”"},{"v":10,"ve":10,"vl":"10","bn":"সে ঈসাকে বারবার কাকুতি-মিনতি করে বলল যেন তিনি সেই এলাকা থেকে তাদের বের করে না দেন।"},{"v":11,"ve":11,"vl":"11","bn":"সেই সময় সেই জায়গার কাছে পাহাড়ের গায়ে খুব বড় এক পাল শূকর চরছিল।"},{"v":12,"ve":12,"vl":"12","bn":"ভূতেরা ঈসাকে মিনতি করে বলল, “ঐ শূকরের পালের মধ্যে আমাদের পাঠিয়ে দিন; ওদের মধ্যে আমাদের ঢুকতে দিন।”"},{"v":13,"ve":13,"vl":"13","bn":"ঈসা অনুমতি দিলে পর সেই ভূতেরা বের হয়ে শূকরগুলোর মধ্যে গেল। তাতে সমস্ত শূকর ঢালু পার দিয়ে জোরে দৌড়ে গেল এবং সাগরের মধ্যে পড়ে ডুবে মরল। সেই পালের মধ্যে প্রায় দু’হাজার শূকর ছিল।"},{"v":14,"ve":14,"vl":"14","bn":"যারা শূকর চরাচ্ছিল তারা তখন পালিয়ে গিয়ে গ্রামে এবং তার আশেপাশের সব জায়গায় এই খবর দিল। তখন লোকেরা দেখতে আসল কি হয়েছে।"},{"v":15,"ve":15,"vl":"15","bn":"তারা ঈসার কাছে এসে দেখল, যাকে অনেকগুলো ভূতে পেয়েছিল সেই লোকটা কাপড়-চোপড় পরে সুস্থ মনে বসে আছে। এ দেখে লোকেরা ভয় পেল।"},{"v":16,"ve":16,"vl":"16","bn":"এই ঘটনা যারা দেখেছিল তারা সেই ভূতে পাওয়া লোকটার বিষয় ও সেই শূকরগুলোর বিষয় লোকদের জানাল।"},{"v":17,"ve":17,"vl":"17","bn":"এতে লোকেরা ঈসাকে অনুরোধ করতে লাগল যেন তিনি তাদের এলাকা ছেড়ে চলে যান।"},{"v":18,"ve":18,"vl":"18","bn":"ঈসা যখন নৌকায় উঠছিলেন তখন যাকে ভূতে পেয়েছিল সেই লোকটি তাঁর সংগে যাবার জন্য মিনতি করতে লাগল।"},{"v":19,"ve":19,"vl":"19","bn":"কিন্তু ঈসা তাঁকে এই বলে বিদায় করলেন, “তুমি তোমার বাড়ীতে ফিরে যাও এবং মাবুদ তোমার জন্য কত বড় কাজ করেছেন ও তোমার উপর কত দয়া দেখিয়েছেন তা গিয়ে তোমার বাড়ীর লোকদের বল।”"},{"v":20,"ve":20,"vl":"20","bn":"লোকটি তখন চলে গেল এবং ঈসা তার জন্য কত বড় কাজ করেছেন তা দেকাপলি এলাকায় বলে বেড়াতে লাগল। তাতে সবাই আশ্চর্য হল।"},{"heading":"একটি মৃত বালিকা ও একজন অসুস্থ স্ত্রীলোক","v":21,"ve":21,"vl":"21","bn":"ঈসা যখন নৌকায় করে আবার সাগরের অন্য পারে গেলেন তখন তাঁর চারপাশে অনেক লোক এসে ভিড় করল। তিনি তখনও সাগরের পারে ছিলেন।"},{"v":22,"ve":22,"vl":"22","bn":"সেই সময় যায়ীর নামে ইহুদী মজলিস-খানার একজন নেতা সেখানে আসলেন এবং ঈসাকে দেখে তাঁর পায়ের উপর উবুড় হয়ে পড়লেন।"},{"v":23,"ve":23,"vl":"23","bn":"তিনি ঈসাকে মিনতি করে বললেন, “আমার মেয়েটা মারা যাবার মত হয়েছে। আপনি এসে তার উপর আপনার হাত রাখুন; তাতে সে সুস্থ হয়ে উঠবে।”"},{"v":24,"ve":24,"vl":"24","bn":"তখন ঈসা তাঁর সংগে চললেন। অনেক লোক ঈসার সংগে সংগে যাচ্ছিল এবং তাঁর চারপাশে ঠেলাঠেলি করছিল।"},{"v":25,"ve":25,"vl":"25","bn":"সেই ভিড়ের মধ্যে একজন স্ত্রীলোক ছিল যে বারো বছর ধরে রক্তস্রাব রোগে ভুগছিল।"},{"v":26,"ve":26,"vl":"26","bn":"অনেক ডাক্তারের হাতে সে অনেক কষ্ট পেয়েছিল, আর তার যা কিছু ছিল সবই সে খরচ করেছিল, কিন্তু ভাল হবার বদলে দিন দিনই তার অবস্থা খারাপ হচ্ছিল।"},{"v":27,"ve":27,"vl":"27","bn":"ঈসার বিষয় শুনে সে ভিড়ের মধ্যেই ঈসার ঠিক পিছনে এসে তাঁর চাদরটা ছুঁলো,"},{"v":28,"ve":28,"vl":"28","bn":"কারণ সে ভেবেছিল যদি কেবল তাঁর কাপড় সে ছুঁতে পারে তাহলেই সে ভাল হয়ে যাবে।"},{"v":29,"ve":29,"vl":"29","bn":"ঈসার চাদরটা ছোঁয়ার সংগে সংগেই তার রক্তস্রাব বন্ধ হল এবং সে তার নিজের শরীরের মধ্যেই বুঝল তার অসুখ ভাল হয়ে গেছে।"},{"v":30,"ve":30,"vl":"30","bn":"ঈসা তখনই বুঝলেন তাঁর মধ্য থেকে শক্তি বের হয়েছে। সেইজন্য তিনি ভিড়ের চারদিকে তাকিয়ে জিজ্ঞাসা করলেন, “কে আমার কাপড় ছুঁলো?”"},{"v":31,"ve":31,"vl":"31","bn":"তাঁর সাহাবীরা বললেন, “আপনি তো দেখছেন লোকে আপনার চারপাশে ঠেলাঠেলি করছে, আর তবুও আপনি বলছেন, কে আপনাকে ছুঁলো?”"},{"v":32,"ve":32,"vl":"32","bn":"এই কাজ কে করেছে তা দেখবার জন্য তবুও ঈসা চারদিকে তাকাতে লাগলেন।"},{"v":33,"ve":33,"vl":"33","bn":"সেই স্ত্রীলোকটির যা হয়েছে তা বুঝে সে কাঁপতে কাঁপতে এসে ঈসার পায়ে পড়ল এবং সব বিষয় জানাল।"},{"v":34,"ve":34,"vl":"34","bn":"ঈসা তাঁকে বললেন, “মা, তুমি বিশ্বাস করেছ বলে সুস্থ হয়েছ। শান্তিতে চলে যাও, তোমার আর এই কষ্ট না হোক।”"},{"v":35,"ve":35,"vl":"35","bn":"ঈসা তখনও কথা বলছিলেন, এমন সময় সেই মজলিস-খানার নেতা যায়ীরের ঘর থেকে কয়েকজন লোক এসে যায়ীরকে বলল, “আপনার মেয়েটা মারা গেছে; হুজুরকে আর কষ্ট দেবেন না।”"},{"v":36,"ve":36,"vl":"36","bn":"সেই লোকগুলোর কথা শুনে ঈসা যায়ীরকে বললেন, “ভয় করবেন না, কেবল বিশ্বাস করুন।”"},{"v":37,"ve":37,"vl":"37","bn":"ঈসা কেবল পিতর, ইয়াকুব ও ইয়াকুবের ভাই ইউহোন্নাকে তাঁর সংগে নিলেন।"},{"v":38,"ve":38,"vl":"38","bn":"পরে যায়ীরের বাড়ীতে এসে তিনি দেখলেন খুব গোলমাল হচ্ছে। লোকেরা জোরে জোরে কান্নাকাটি করছে।"},{"v":39,"ve":39,"vl":"39","bn":"ঈসা ভিতরে গিয়ে লোকদের বললেন, “আপনারা কেন গোলমাল ও কান্নাকাটি করছেন? মেয়েটি মারা যায় নি, ঘুমাচ্ছে।”"},{"v":40,"ve":40,"vl":"40","bn":"এই কথা শুনে লোকেরা হাসাহাসি করতে লাগল। তখন ঈসা তাদের সবাইকে ঘর থেকে বাইরে যেতে বললেন। তারপর তিনি মেয়েটির মা-বাবা এবং তাঁর সংগের সাহাবীদের নিয়ে মেয়েটি যে ঘরে ছিল সেই ঘরে ঢুকলেন।"},{"v":41,"ve":42,"vl":"41-42","bn":"মেয়েটির বয়স ছিল বারো বছর। ঈসা মেয়েটির হাত ধরে বললেন, “টালিথা কুম্‌,” অর্থাৎ “খুকী, তোমাকে বলছি, ওঠো।” আর তখনই মেয়েটি উঠে হেঁটে বেড়াতে লাগল। এতে তাঁরা খুব আশ্চর্য হয়ে গেলেন।"},{"v":43,"ve":43,"vl":"43","bn":"এই ঘটনার কথা কাউকে না জানাবার জন্য ঈসা কড়া হুকুম দিলেন এবং মেয়েটিকে কিছু খেতে দিতে বললেন।"}],"6":[{"heading":"নিজের গ্রামে হযরত ঈসা মসীহের অসম্মান","v":1,"ve":1,"vl":"1","bn":"এর পর ঈসা সেই জায়গা ছেড়ে নিজের গ্রামে গেলেন,"},{"v":2,"ve":2,"vl":"2","bn":"আর তাঁর সাহাবীরাও তাঁর সংগে গেলেন। বিশ্রামবারে তিনি মজলিস-খানায় গিয়ে শিক্ষা দিতে লাগলেন। অনেক লোক তাঁর কথা শুনে আশ্চর্য হয়ে বলতে লাগল, “এই লোক কোথা থেকে এই সব পেল? এই যে জ্ঞান তাকে দেওয়া হয়েছে, এ-ই বা কি? আবার সে অলৌকিক চিহ্ন-কাজও করছে।"},{"v":3,"ve":3,"vl":"3","bn":"এ কি সেই ছুতার মিস্ত্রি নয়? এ কি মরিয়মের ছেলে নয়? ইয়াকুব, ইউসুফ, এহুদা ও শিমোনের ভাই নয়? তার বোনেরা কি এখানে আমাদের মধ্যে নেই?” এইভাবে ঈসাকে নিয়ে লোকদের মনে বাধা আসতে লাগল।"},{"v":4,"ve":4,"vl":"4","bn":"তখন ঈসা তাদের বললেন, “নিজের গ্রাম, নিজের আত্মীয়-স্বজন ও নিজের বাড়ী ছাড়া আর সব জায়গাতেই নবীরা সম্মান পান।”"},{"v":5,"ve":5,"vl":"5","bn":"তারপর তিনি কয়েকজন অসুস্থ লোকের উপর হাত রেখে তাদের সুস্থ করলেন, কিন্তু সেখানে আর কোন অলৌকিক চিহ্ন-কাজ করা সম্ভব হল না।"},{"v":6,"ve":6,"vl":"6","bn":"লোকেরা তাঁর উপর ঈমান আনল না দেখে তিনি খুব আশ্চর্য হলেন। এর পরে ঈসা গ্রামে গ্রামে গিয়ে লোকদের শিক্ষা দিতে লাগলেন।"},{"heading":"সাহাবীদের তবলিগ-যাত্রা","v":7,"ve":7,"vl":"7","bn":"পরে তিনি তাঁর সেই বারোজন সাহাবীকে নিজের কাছে ডাকলেন এবং তবলিগ করবার জন্য দু’জন দু’জন করে পাঠিয়ে দিলেন। তিনি ভূতদের উপরে তাঁদের ক্ষমতা দিলেন।"},{"v":8,"ve":8,"vl":"8","bn":"যাত্রাপথের জন্য একটা লাঠি ছাড়া আর কিছুই তিনি সাহাবীদের নিতে দিলেন না। রুটি, থলি, কোমর-বাঁধনিতে পয়সা পর্যন্ত নিতে তিনি তাঁদের নিষেধ করলেন।"},{"v":9,"ve":9,"vl":"9","bn":"তিনি তাঁদের জুতা পরতে বললেন বটে, কিন্তু একটার বেশী কোর্তা পরতে নিষেধ করলেন।"},{"v":10,"ve":10,"vl":"10","bn":"তিনি তাঁদের আরও বললেন, “তোমরা যে বাড়ীতে ঢুকবে সেই গ্রাম ছেড়ে না যাওয়া পর্যন্ত সেই বাড়ীতেই থেকো।"},{"v":11,"ve":11,"vl":"11","bn":"কোন জায়গার লোকেরা যদি তোমাদের গ্রহণ না করে কিংবা তোমাদের কথা না শোনে, তবে সেই জায়গা ছেড়ে চলে যাবার সময়ে তোমাদের পায়ের ধুলা ঝেড়ে ফেলো যেন সেটাই তাদের বিরুদ্ধে সাক্ষ্য হয়।”"},{"v":12,"ve":12,"vl":"12","bn":"তখন সাহাবীরা গিয়ে তবলিগ করতে লাগলেন যেন লোকেরা তওবা করে।"},{"v":13,"ve":13,"vl":"13","bn":"তাঁরা অনেক ভূত ছাড়ালেন এবং অনেক অসুস্থ লোকের মাথায় তেল দিয়ে তাদের সুস্থ করলেন।"},{"heading":"হযরত ইয়াহিয়া (আঃ)-এর শাহাদাত বরণ","v":14,"ve":14,"vl":"14","bn":"ঈসার সুনাম চারদিকে ছড়িয়ে পড়েছিল বলে বাদশাহ্‌ হেরোদ ঈসার কথা শুনতে পেয়েছিলেন। কোন কোন লোক বলছিল, “উনিই সেই তরিকাবন্দীদাতা ইয়াহিয়া। তিনি মৃত্যু থেকে বেঁচে উঠেছেন বলে এই সব অলৌকিক চিহ্ন-কাজ করছেন।”"},{"v":15,"ve":15,"vl":"15","bn":"কেউ কেউ বলছিল, “উনি ইলিয়াস নবী”; আবার কেউ কেউ বলছিল, “অনেক দিন আগেকার নবীদের মত উনিও একজন নবী।”"},{"v":16,"ve":16,"vl":"16","bn":"এই সব কথা শুনে হেরোদ বললেন, “উনি ইয়াহিয়া, যাঁর মাথা কেটে ফেলবার হুকুম আমি দিয়েছিলাম। আবার উনি বেঁচে উঠেছেন।”"},{"v":17,"ve":18,"vl":"17-18","bn":"এই ঘটনার আগে হেরোদ লোক পাঠিয়ে ইয়াহিয়াকে ধরেছিলেন এবং তাঁকে বেঁধে জেলখানায় রেখেছিলেন। হেরোদ তাঁর ভাই ফিলিপের স্ত্রী হেরোদিয়ার জন্যই এটা করেছিলেন। হেরোদ হেরোদিয়াকে বিয়ে করেছিলেন বলে ইয়াহিয়া বারবার হেরোদকে বলতেন, “আপনার ভাইয়ের স্ত্রীকে বিয়ে করা আপনার উচিত হয় নি।”"},{"v":19,"ve":19,"vl":"19","bn":"এইজন্য ইয়াহিয়ার উপর হেরোদিয়ার খুব রাগ ছিল। সে ইয়াহিয়াকে হত্যা করতে চেয়েছিল,"},{"v":20,"ve":20,"vl":"20","bn":"কিন্তু হেরোদ ইয়াহিয়াকে ভয় করতেন বলে সে তা করতে পারছিল না। ইয়াহিয়া যে একজন আল্লাহ্‌ভক্ত ও পবিত্র লোক হেরোদ তা জানতেন, তাই তিনি ইয়াহিয়াকে বিপদের হাত থেকে রক্ষা করতেন। ইয়াহিয়ার কথা শুনবার সময় মনে খুব অস্বস্তি বোধ করলেও হেরোদ তাঁর কথা শুনতে ভালবাসতেন।"},{"v":21,"ve":21,"vl":"21","bn":"শেষে হেরোদিয়া একটা সুযোগ পেল। হেরোদ নিজের জন্মদিনে তাঁর বড় বড় রাজকর্মচারী, সেনাপতি ও গালীল প্রদেশের প্রধান লোকদের জন্য একটা মেজবানী দিলেন।"},{"v":22,"ve":22,"vl":"22","bn":"হেরোদিয়ার মেয়ে সেই মেজবানীসভায় নাচ দেখিয়ে হেরোদ ও ভোজে দাওয়াতী লোকদের সন্তুষ্ট করল। তখন বাদশাহ্‌ মেয়েটিকে বললেন, “তুমি যা চাও আমি তোমাকে তা-ই দেব।”"},{"v":23,"ve":23,"vl":"23","bn":"হেরোদ মেয়েটির কাছে কসম খেয়ে বললেন, “তুমি যা চাও আমি তা-ই তোমাকে দেব। এমন কি, আমার রাজ্যের অর্ধেক পর্যন্তও দেব।”"},{"v":24,"ve":24,"vl":"24","bn":"মেয়েটি গিয়ে তার মাকে বলল, “আমি কি চাইব?” তার মা বলল, “তরিকাবন্দীদাতা ইয়াহিয়ার মাথা।”"},{"v":25,"ve":25,"vl":"25","bn":"মেয়েটি তখনই গিয়ে বাদশাহ্‌কে বলল, “একটা থালায় করে আমি এখনই তরিকাবন্দীদাতা ইয়াহিয়ার মাথাটা চাই।”"},{"v":26,"ve":26,"vl":"26","bn":"এই কথা শুনে বাদশাহ্‌ হেরোদ খুব দুঃখিত হলেন, কিন্তু ভোজে দাওয়াতী লোকদের সামনে কসম খেয়েছিলেন বলে মেয়েটিকে ফিরিয়ে দিতে চাইলেন না।"},{"v":27,"ve":28,"vl":"27-28","bn":"তিনি তখনই ইয়াহিয়ার মাথা কেটে আনবার জন্য একজন জল্লাদকে হুকুম দিলেন। সেই জল্লাদ জেলখানায় গিয়ে ইয়াহিয়ার মাথা কেটে একটা থালায় করে তা নিয়ে আসল। বাদশাহ্‌ সেটা মেয়েটিকে দিলে পর সে তা নিয়ে গিয়ে তার মাকে দিল।"},{"v":29,"ve":29,"vl":"29","bn":"এই খবর পেয়ে ইয়াহিয়ার সাহাবীরা এসে তাঁর লাশটা নিয়ে গিয়ে দাফন করলেন।"},{"heading":"পাঁচ হাজার লোককে খাওয়ানো","v":30,"ve":30,"vl":"30","bn":"ঈসা যে বারোজন সাহাবীকে পাঠিয়েছিলেন তাঁরা ফিরে আসলেন এবং যা যা করেছিলেন ও শিক্ষা দিয়েছিলেন সবই তাঁকে জানালেন।"},{"v":31,"ve":31,"vl":"31","bn":"সেই সময় অনেক লোক সেখানে যাওয়া-আসা করছিল বলে সাহাবীরা কিছু খাওয়ার সুযোগও পেলেন না। সেইজন্য ঈসা তাঁদের বললেন, “তোমরা আমার সংগে কোন একটা নির্জন জায়গায় এসে কিছুক্ষণ বিশ্রাম কর।”"},{"v":32,"ve":32,"vl":"32","bn":"তাঁরা নৌকায় করে একটা নির্জন জায়গায় গেলেন।"},{"v":33,"ve":33,"vl":"33","bn":"তাঁদের যেতে দেখে অনেকেই কিন্তু তাঁদের চিনতে পারল এবং আশেপাশের গ্রাম থেকে দৌড়ে গিয়ে তাঁদের আগেই সেখানে উপস্থিত হল।"},{"v":34,"ve":34,"vl":"34","bn":"ঈসা নৌকা থেকে নেমে অনেক লোকের ভিড় দেখতে পেলেন। এই লোকদের জন্য ঈসার খুব মমতা হল কারণ এদের দশা রাখালহীন ভেড়ার মত ছিল। ঈসা তাদের অনেক বিষয় শিক্ষা দিতে লাগলেন।"},{"v":35,"ve":35,"vl":"35","bn":"যখন দিন শেষ হয়ে আসল তখন সাহাবীরা এসে ঈসাকে বললেন, “জায়গাটা নির্জন, বেলাও প্রায় ডুবে গেছে।"},{"v":36,"ve":36,"vl":"36","bn":"লোকদের বিদায় করে দিন যেন তারা আশেপাশের পাড়ায় ও গ্রামে গিয়ে নিজেদের জন্য কিছু খাবার কিনতে পারে।”"},{"v":37,"ve":37,"vl":"37","bn":"ঈসা বললেন, “তোমরাই ওদের খেতে দাও।” সাহাবীরা তাঁকে বললেন, “আমরা গিয়ে দু’শো দীনারের রুটি কিনে এনে কি তাদের খেতে দেব?”"},{"v":38,"ve":38,"vl":"38","bn":"ঈসা বললেন, “তোমাদের কাছে কয়টা রুটি আছে গিয়ে দেখ।” সাহাবীরা দেখে এসে বললেন, “পাঁচটা রুটি আর দু’টা মাছ আছে।”"},{"v":39,"ve":39,"vl":"39","bn":"তখন ঈসা সাহাবীদের হুকুম দিলেন যেন তাঁরা সবুজ ঘাসের উপর লোকদের বসিয়ে দেন।"},{"v":40,"ve":40,"vl":"40","bn":"লোকেরা একশো একশো করে, পঞ্চাশ পঞ্চাশ জন করে সারি সারি বসে গেল।"},{"v":41,"ve":41,"vl":"41","bn":"ঈসা সেই পাঁচটা রুটি আর দু’টা মাছ নিয়ে বেহেশতের দিকে তাকিয়ে আল্লাহ্‌কে শুকরিয়া জানালেন, আর লোকদের দেবার জন্য রুটি ভেংগে সাহাবীদের হাতে দিলেন। এইভাবে তিনি সবাইকে মাছও ভাগ করে দিলেন।"},{"v":42,"ve":42,"vl":"42","bn":"তারা সকলে পেট ভরে খেল।"},{"v":43,"ve":43,"vl":"43","bn":"তার পরে সাহাবীরা বাকী রুটি ও মাছের টুকরা তুলে নিয়ে বারোটা টুকরি ভরতি করলেন।"},{"v":44,"ve":44,"vl":"44","bn":"যারা খেয়েছিল তাদের মধ্যে পুরুষের সংখ্যাই ছিল পাঁচ হাজার।"},{"heading":"পানির উপর হাঁটা","v":45,"ve":45,"vl":"45","bn":"ঈসা এর পরেই তাঁর সাহাবীদের তাগাদা দিলেন যেন তাঁরা নৌকায় উঠে তাঁর আগে সাগরের অন্য পারে বৈৎসৈদা গ্রামে যান, আর এদিকে তিনি লোকদের বিদায় করতে লাগলেন।"},{"v":46,"ve":46,"vl":"46","bn":"লোকদের বিদায় দিয়ে তিনি মুনাজাত করবার জন্য পাহাড়ে উঠে গেলেন।"},{"v":47,"ve":47,"vl":"47","bn":"যখন রাত হল তখন সাহাবীদের নৌকাটা সাগরের মাঝখানে ছিল এবং ঈসা একা ডাংগায় ছিলেন।"},{"v":48,"ve":48,"vl":"48","bn":"ঈসা দেখলেন সাহাবীরা খুব কষ্ট করে দাঁড় বাইছেন, কারণ বাতাস তাঁদের উল্টাদিকে ছিল। প্রায় শেষ রাতের দিকে ঈসা সাগরের উপর দিয়ে হেঁটে সাহাবীদের কাছে আসলেন এবং তাঁদের ফেলে এগিয়ে যাচ্ছিলেন।"},{"v":49,"ve":49,"vl":"49","bn":"সাহাবীরা কিন্তু তাঁকে সাগরের উপর দিয়ে হাঁটতে দেখে ভূত মনে করে চিৎকার করে উঠলেন,"},{"v":50,"ve":50,"vl":"50","bn":"কারণ তাঁকে দেখে সবাই ভয় পেয়েছিলেন। ঈসা তখনই সাহাবীদের সংগে কথা বললেন। তিনি তাঁদের বললেন, “এ তো আমি; ভয় কোরো না, সাহস কর।”"},{"v":51,"ve":51,"vl":"51","bn":"ঈসা সাহাবীদের নৌকায় উঠলে পর বাতাস থেমে গেল। এতে সাহাবীরা খুব অবাক হয়ে গেলেন,"},{"v":52,"ve":52,"vl":"52","bn":"কারণ এর আগে রুটি খাওয়াবার ব্যাপারটা তাঁরা বুঝতে পারেন নি; তাঁদের মন কঠিন হয়েই রইল।"},{"v":53,"ve":53,"vl":"53","bn":"ঈসা ও তাঁর সাহাবীরা সাগর পার হয়ে গিনেষরৎ এলাকায় এসে নৌকা বাঁধলেন।"},{"v":54,"ve":55,"vl":"54-55","bn":"তাঁরা নৌকা থেকে নামতেই লোকেরা ঈসাকে চিনতে পেরে ঐ এলাকার সব জায়গায় দৌড়াদৌড়ি করতে লাগল। তারপর তিনি কোথায় আছেন তা জেনে নিয়ে তারা মাদুরের উপরে করে রোগীদের তাঁর কাছে বয়ে নিয়ে গেল।"},{"v":56,"ve":56,"vl":"56","bn":"শহরে, গ্রামে বা পাড়ায়, যেখানেই তিনি যেতেন সেখানকার লোকেরা রোগীদের এনে বাজারের মধ্যে জড়ো করত। তারা ঈসাকে মিনতি করত যেন রোগীরা তাঁর চাদরের কিনারাটা কেবল ছুঁতে পারে, আর যারা তাঁকে ছুঁতো তারা সুস্থ হত।"}],"7":[{"heading":"পূর্বপুরুষদের দেওয়া নিয়ম","v":1,"ve":1,"vl":"1","bn":"যাঁরা জেরুজালেম থেকে এসেছিলেন এমন কয়েকজন ফরীশী ও আলেম ঈসার কাছে একত্র হলেন।"},{"v":2,"ve":2,"vl":"2","bn":"তাঁরা দেখলেন, ঈসার সাহাবীদের মধ্যে কয়েকজন হাত না ধুয়ে নাপাকভাবে খেতে বসেছেন।"},{"v":3,"ve":3,"vl":"3","bn":"ফরীশীরা ও সমস্ত ইহুদীরা পুরানো দিনের আলেমদের দেওয়া যে নিয়ম চলে আসছে সেই নিয়ম মত হাত না ধুয়ে খান না।"},{"v":4,"ve":4,"vl":"4","bn":"বাজার থেকে এসে তাঁরা হাত-পা না ধুয়ে কিছু খান না। এছাড়া তাঁরা আরও অনেক রকম নিয়ম পালন করে থাকেন, যেমন বাসন-কোসন, পেয়ালা ইত্যাদি ধোয়া।"},{"v":5,"ve":5,"vl":"5","bn":"সেইজন্য ফরীশী ও আলেমেরা ঈসাকে জিজ্ঞাসা করলেন, “পুরানো দিনের আলেমদের দেওয়া যে নিয়ম চলে আসছে আপনার সাহাবীরা তা মেনে চলে না কেন? তারা তো হাত না ধুয়েই খায়।”"},{"v":6,"ve":6,"vl":"6","bn":"ঈসা জবাব দিলেন, “আপনারা ভণ্ড! আপনাদের বিষয়ে নবী ইশাইয়া ঠিক কথাই বলেছিলেন। তাঁর কিতাবে লেখা আছে: এই লোকেরা মুখেই আমাকে সম্মান করে, কিন্তু তাদের দিল আমার কাছ থেকে দূরে থাকে।"},{"v":7,"ve":7,"vl":"7","bn":"তারা মিথ্যাই আমার এবাদত করে, তাদের দেওয়া শিক্ষা মানুষের তৈরী কতগুলো নিয়ম মাত্র।"},{"v":8,"ve":8,"vl":"8","bn":"আপনারা তো আল্লাহ্‌র দেওয়া হুকুমগুলো বাদ দিয়ে মানুষের দেওয়া চলতি নিয়ম পালন করছেন।”"},{"v":9,"ve":9,"vl":"9","bn":"ঈসা তাঁদের আরও বললেন, “আল্লাহ্‌র হুকুম বাদ দিয়ে নিজেদের চলতি নিয়ম পালন করবার জন্য খুব ভাল উপায়ই আপনাদের জানা আছে।"},{"v":10,"ve":10,"vl":"10","bn":"যেমন ধরুন, মূসা বলেছেন, ‘মা-বাবাকে সম্মান কোরো’ এবং ‘যার কথায় মা-বাবার প্রতি অসম্মান থাকে তাকে অবশ্যই মেরে ফেলতে হবে।’"},{"v":11,"ve":11,"vl":"11","bn":"কিন্তু আপনারা বলে থাকেন, যদি কেউ তার মা কিংবা বাবাকে বলে, ‘আমার যে জিনিসের দ্বারা তোমার সাহায্য হতে পারত তা কোরবান,’ অর্থাৎ আল্লাহ্‌র কাছে কোরবানী করা হয়েছে,"},{"v":12,"ve":12,"vl":"12","bn":"তবে মা-বাবার জন্য তাকে আর কিছু করতে হয় না।"},{"v":13,"ve":13,"vl":"13","bn":"এইভাবে আপনারা আপনাদের চলতি নিয়ম শিক্ষা দিয়ে আল্লাহ্‌র কালাম বাতিল করেছেন। এছাড়া আপনারা আরও এই রকম অনেক কাজ করে থাকেন।”"},{"v":14,"ve":14,"vl":"14","bn":"এর পরে ঈসা লোকদের আবার তাঁর কাছে ডেকে বললেন, “আপনারা সবাই আমার কথা শুনুন ও বুঝুন।"},{"v":15,"ve":16,"vl":"15-16","bn":"বাইরে থেকে যা মানুষের ভিতরে যায় তা মানুষকে নাপাক করতে পারে না, বরং মানুষের মধ্য থেকে যা বের হয়ে আসে তা-ই মানুষকে নাপাক করে।”"},{"v":17,"ve":17,"vl":"17","bn":"এর পরে ঈসা যখন লোকদের ছেড়ে ঘরে ঢুকলেন, তখন সাহাবীরা সেই কথার মানে তাকে জিজ্ঞাসা করলেন।"},{"v":18,"ve":18,"vl":"18","bn":"ঈসা তাঁদের বললেন, “তোমরা কি এতই অবুঝ? তোমরা কি বোঝ না যে, বাইরে থেকে যা মানুষের ভিতরে ঢোকে তা তাকে নাপাক করতে পারে না?"},{"v":19,"ve":19,"vl":"19","bn":"এর কারণ হল, তা তো তার অন্তরে ঢোকে না কিন্তু পেটে ঢোকে এবং পরে শরীর থেকে বের হয়ে যায়।” এই কথাতেই ঈসা বুঝিয়ে দিলেন যে, সব খাবারই হালাল।"},{"v":20,"ve":20,"vl":"20","bn":"ঈসা আরও বললেন, “মানুষের ভিতর থেকে যা বের হয়ে আসে তা-ই মানুষকে নাপাক করে,"},{"v":21,"ve":21,"vl":"21","bn":"কারণ মানুষের ভিতর, অর্থাৎ অন্তর থেকেই খারাপ চিন্তা, সমস্ত রকম জেনা, চুরি, খুন,"},{"v":22,"ve":22,"vl":"22","bn":"লোভ, অন্যের ক্ষতি করবার ইচ্ছা, ছলনা, লমপটতা, হিংসা, নিন্দা, অহংকার এবং মূর্খতা বের হয়ে আসে।"},{"v":23,"ve":23,"vl":"23","bn":"এই সব খারাপী মানুষের ভিতর থেকেই বের হয়ে আসে এবং মানুষকে নাপাক করে।”"},{"heading":"বিদেশী স্ত্রীলোকের বিশ্বাস","v":24,"ve":24,"vl":"24","bn":"এর পরে ঈসা সেই জায়গা ছেড়ে টায়ার এলাকায় গেলেন। তিনি একটা ঘরে ঢুকলেন এবং চাইলেন যেন কেউ তা জানতে না পারে, কিন্তু তিনি লুকিয়ে থাকতে পারলেন না।"},{"v":25,"ve":25,"vl":"25","bn":"সেখানে এমন একজন স্ত্রীলোক ছিল যার মেয়েকে ভূতে পেয়েছিল। সেই স্ত্রীলোকটি ঈসার বিষয় শুনতে পেয়ে তখনই এসে ঈসার পায়ে পড়ল।"},{"v":26,"ve":26,"vl":"26","bn":"স্ত্রীলোকটি ছিল অ-ইহুদী এবং সিরিয়া-ফিনিশিয়াতে জন্মগ্রহণ করেছিল। সে ঈসার কাছে কাকুতি-মিনতি করতে লাগল যেন তিনি তার মেয়েটির মধ্য থেকে ভূত দূর করে দেন।"},{"v":27,"ve":27,"vl":"27","bn":"ঈসা তাকে বললেন, “আগে ছেলেমেয়েরা পেট ভরে খাক, কারণ ছেলেমেয়েদের খাবার নিয়ে কুকুরের সামনে ফেলা ভাল নয়।”"},{"v":28,"ve":28,"vl":"28","bn":"তাতে সেই স্ত্রীলোকটি বলল, “হুজুর, আপনি ঠিকই বলেছেন, কিন্তু ছেলেমেয়েদের খাবারের যে সব টুকরা টেবিলের নীচে পড়ে তা তো কুকুরেই খায়।”"},{"v":29,"ve":29,"vl":"29","bn":"ঈসা তাকে বললেন, “কথাটা তুমি খুব ভাল বলেছ। এখন যাও; গিয়ে দেখ, ভূত তোমার মেয়েটির মধ্য থেকে বের হয়ে গেছে।”"},{"v":30,"ve":30,"vl":"30","bn":"সেই স্ত্রীলোকটি তখন বাড়ীতে ফিরে গিয়ে দেখল, তার মেয়েটি বিছানায় শুয়ে আছে এবং ভূত তার মধ্য থেকে বের হয়ে গেছে।"},{"heading":"বধির ও তোতলা লোকটি সুস্থ হল","v":31,"ve":31,"vl":"31","bn":"এর পরে ঈসা টায়ার এলাকা ছেড়ে সিডন শহরের মধ্য দিয়ে গালীল সাগরের কাছে দেকাপলি এলাকার গ্রামগুলোতে গেলেন।"},{"v":32,"ve":32,"vl":"32","bn":"সেখানে কয়েকজন লোক একটা বধির ও তোতলা লোককে ঈসার কাছে নিয়ে আসল এবং কাকুতি-মিনতি করতে লাগল যেন তিনি সেই লোকটির উপরে তাঁর হাত রাখেন।"},{"v":33,"ve":33,"vl":"33","bn":"ঈসা ভিড়ের মধ্য থেকে সেই লোকটিকে একপাশে নিয়ে গিয়ে তার দুই কানের মধ্যে নিজের আংগুল দিলেন। পরে থুথু ফেলে লোকটার জিভ্‌ ছুঁলেন।"},{"v":34,"ve":34,"vl":"34","bn":"তারপর তিনি আসমানের দিকে তাকিয়ে দীর্ঘনিঃশ্বাস ফেলে লোকটিকে বললেন, “এপ্‌ফাথা,” অর্থাৎ “খুলে যাও।”"},{"v":35,"ve":35,"vl":"35","bn":"তাতে লোকটার কানও খুলে গেল, জিভও খুলে গেল এবং সে স্পষ্টভাবে কথা বলতে লাগল।"},{"v":36,"ve":36,"vl":"36","bn":"ঈসা এই বিষয়ে কাউকে বলতে লোকদের নিষেধ করলেন। কিন্তু তিনি যতই তাদের নিষেধ করলেন ততই তারা সেই বিষয়ে আরও বেশী করে বলাবলি করতে লাগল।"},{"v":37,"ve":37,"vl":"37","bn":"এই ঘটনায় লোকেরা খুব আশ্চর্য হয়ে বলল, “ইনি সব কাজ কত নিখুঁতভাবে করেন। ইনি বধিরদের শুনবার শক্তি ও বোবাদের কথা বলবার শক্তি দেন।”"}],"8":[{"heading":"চার হাজার লোককে খাওয়ানো","v":1,"ve":1,"vl":"1","bn":"পরে আবার একদিন অনেক লোকের ভিড় হল। এই সব লোকদের কাছে কোন খাবার ছিল না বলে ঈসা তাঁর সাহাবীদের ডেকে বললেন,"},{"v":2,"ve":2,"vl":"2","bn":"“এই লোকদের জন্য আমার মমতা হচ্ছে, কারণ আজ তিন দিন হল এরা আমার সংগে সংগে আছে, আর এদের কাছে কোন খাবার নেই।"},{"v":3,"ve":3,"vl":"3","bn":"যদি আমি এই অবস্থায় এদের বাড়ী পাঠিয়ে দিই তবে তারা পথেই অজ্ঞান হয়ে পড়বে, কারণ এদের মধ্যে অনেকেই অনেক দূর থেকে এসেছে।”"},{"v":4,"ve":4,"vl":"4","bn":"সাহাবীরা বললেন, “কিন্তু এই নির্জন জায়গায় এদের খাওয়াবার জন্য কে কোথা থেকে এত রুটি পাবে?”"},{"v":5,"ve":5,"vl":"5","bn":"ঈসা জিজ্ঞাসা করলেন, “তোমাদের কাছে কয়টা রুটি আছে?” তাঁরা বললেন, “সাতখানা।”"},{"v":6,"ve":6,"vl":"6","bn":"তিনি লোকদের মাটিতে বসতে হুকুম দিলেন। পরে সেই রুটি সাতখানা নিয়ে তিনি আল্লাহ্‌কে শুকরিয়া জানিয়ে ভাংলেন এবং লোকদের দেবার জন্য সাহাবীদের হাতে দিলেন আর সাহাবীরা তা লোকদের হাতে দিলেন।"},{"v":7,"ve":7,"vl":"7","bn":"সাহাবীদের কাছে কয়েকটা ছোট মাছও ছিল। ঈসা সেই মাছগুলোর জন্যও শুকরিয়া জানালেন এবং তা লোকদের ভাগ করে দেবার জন্য সাহাবীদের বললেন।"},{"v":8,"ve":8,"vl":"8","bn":"লোকেরা পেট ভরে খেল। পরে যে টুকরাগুলো পড়ে রইল সাহাবীরা তা তুলে নিয়ে সাতটা টুকরি ভরতি করলেন।"},{"v":9,"ve":10,"vl":"9-10","bn":"কমবেশী চার হাজার পুরুষ লোক সেখানে ছিল। এর পরে তিনি লোকদের বিদায় দিলেন এবং সাহাবীদের সংগে একটা নৌকায় উঠে দল্‌মনুথা এলাকায় গেলেন।"},{"v":11,"ve":11,"vl":"11","bn":"সেখানে ফরীশীরা এসে ঈসার সংগে তর্ক করতে লাগলেন এবং তাঁকে পরীক্ষা করবার জন্য বেহেশত থেকে কোন একটা চিহ্ন দেখতে চাইলেন।"},{"v":12,"ve":12,"vl":"12","bn":"এতে ঈসা গভীর দীর্ঘনিঃশ্বাস ফেলে বললেন, “এই কালের লোকেরা চিহ্নের তালাশ করে কেন? আমি আপনাদের সত্যিই বলছি, কোন চিহ্নই এদের দেখানো হবে না।”"},{"v":13,"ve":13,"vl":"13","bn":"তারপর তিনি তাঁদের ছেড়ে আবার নৌকায় উঠে সাগরের অন্য পারে গেলেন।"},{"heading":"সাহাবীদের সাবধান করা","v":14,"ve":14,"vl":"14","bn":"সাহাবীরা সংগে করে রুটি নিতে ভুলে গিয়েছিলেন। নৌকার মধ্যে তাঁদের কাছে মাত্র একখানা রুটি ছিল।"},{"v":15,"ve":15,"vl":"15","bn":"এই সময় ঈসা বললেন, “তোমরা সতর্ক থাক, ফরীশীদের ও হেরোদের খামি থেকে সাবধান হও।”"},{"v":16,"ve":16,"vl":"16","bn":"এতে সাহাবীরা নিজেদের মধ্যে বলতে লাগলেন, “আমাদের কাছে রুটি নেই বলে উনি এই কথা বলছেন।”"},{"v":17,"ve":17,"vl":"17","bn":"সাহাবীরা কি বিষয়ে বলছেন তা বুঝতে পেরে ঈসা তাঁদের বললেন, “তোমরা কেন বলছ যে, তোমাদের রুটি নেই? তোমরা কি এখনও জান না বা বোঝ না? তোমাদের অন্তর কি কঠিন হয়ে গেছে?"},{"v":18,"ve":18,"vl":"18","bn":"তোমাদের চোখ থাকতেও কি দেখতে পাও না? কান থাকতেও কি শুনতে পাও না? মনেও কি পড়ে না,"},{"v":19,"ve":19,"vl":"19","bn":"যখন আমি পাঁচ হাজার লোকের জন্য পাঁচখানা রুটি ভেংগেছিলাম তখন কত টুকরি রুটির টুকরা তোমরা কুড়িয়ে তুলেছিলে?” সাহাবীরা জবাব দিলেন, “বারো টুকরি।”"},{"v":20,"ve":20,"vl":"20","bn":"ঈসা আবার বললেন, “আমি যখন চার হাজার লোকের জন্য সাতখানা রুটি ভেংগেছিলাম তখন কত টুকরি রুটির টুকরা তোমরা কুড়িয়ে তুলেছিলে?” তাঁরা বললেন, “সাত টুকরি।”"},{"v":21,"ve":21,"vl":"21","bn":"তখন তিনি তাঁদের বললেন, “তাহলে তোমরা কি এখনও বোঝ না?”"},{"heading":"একজন অন্ধকে সুস্থ করা","v":22,"ve":22,"vl":"22","bn":"পরে ঈসা ও তাঁর সাহাবীরা বৈৎসৈদা গ্রামে গেলেন। সেখানকার লোকেরা একজন অন্ধ লোককে তাঁর কাছে নিয়ে আসল এবং লোকটির গায়ে হাত রাখবার জন্য তাঁকে অনুরোধ করতে লাগল।"},{"v":23,"ve":23,"vl":"23","bn":"ঈসা সেই অন্ধ লোকটিকে হাত ধরে গ্রামের বাইরে নিয়ে গেলেন। তার পরে লোকটির চোখে থুথু দিলেন এবং তার গায়ে হাত দিয়ে জিজ্ঞাসা করলেন, “তুমি কি কিছু দেখতে পাচ্ছ?”"},{"v":24,"ve":24,"vl":"24","bn":"লোকটি তাকিয়ে দেখে বলল, “আমি লোক দেখতে পাচ্ছি; তারা দেখতে গাছের মত, আবার হেঁটেও বেড়াচ্ছে।”"},{"v":25,"ve":25,"vl":"25","bn":"ঈসা আর একবার লোকটির চোখের উপরে হাত দিলেন। এইবার তার চোখ খুলে গেল এবং সে দেখবার শক্তি ফিরে পেল। সে পরিষ্কার ভাবে সব কিছু দেখতে লাগল।"},{"v":26,"ve":26,"vl":"26","bn":"ঈসা তাকে তার বাড়ীতে পাঠিয়ে দেবার সময় বললেন, “বৈৎসৈদা গ্রামে যেয়ো না।”"},{"heading":"হযরত পিতরের সাক্ষ্য","v":27,"ve":27,"vl":"27","bn":"তারপর ঈসা ও তাঁর সাহাবীরা সিজারিয়া-ফিলিপি শহরের আশেপাশের গ্রামে গেলেন। যাবার পথে তিনি সাহাবীদের জিজ্ঞাসা করলেন, “আমি কে, এই বিষয়ে লোকে কি বলে?”"},{"v":28,"ve":28,"vl":"28","bn":"সাহাবীরা বললেন, “কেউ কেউ বলে আপনি তরিকাবন্দীদাতা ইয়াহিয়া; কেউ কেউ বলে ইলিয়াস নবী; আবার কেউ কেউ বলে আপনি নবীদের মধ্যে একজন।”"},{"v":29,"ve":29,"vl":"29","bn":"তখন ঈসা বললেন, “কিন্তু তোমরা কি বল, আমি কে?” পিতর জবাব দিলেন, “আপনি সেই মসীহ্‌।”"},{"v":30,"ve":30,"vl":"30","bn":"ঈসা তাঁদের সাবধান করে দিলেন যেন তাঁরা তাঁর সম্বন্ধে কাউকে কিছু না বলেন।"},{"heading":"নিজের মৃত্যুর বিষয়ে হযরত ঈসা মসীহ্‌","v":31,"ve":31,"vl":"31","bn":"পরে ঈসা তাঁর সাহাবীদের এই বলে শিক্ষা দিতে লাগলেন যে, ইব্‌ন্তেআদমকে অনেক দুঃখভোগ করতে হবে। বৃদ্ধ নেতারা, প্রধান ইমামেরা এবং আলেমেরা তাঁকে অগ্রাহ্য করবেন। তাঁকে হত্যা করা হবে এবং তিন দিন পরে তাঁকে মৃত্যু থেকে আবার জীবিত হয়ে উঠতে হবে।"},{"v":32,"ve":32,"vl":"32","bn":"এই সব কথা তিনি স্পষ্টভাবেই বললেন। তখন পিতর ঈসাকে একপাশে নিয়ে গিয়ে অনুযোগ করতে লাগলেন।"},{"v":33,"ve":33,"vl":"33","bn":"ঈসা মুখ ফিরিয়ে সাহাবীদের দিকে তাকালেন এবং পিতরকে ধমক দিয়ে বললেন, “শয়তান, আমার কাছ থেকে দূর হও। আল্লাহ্‌র যা, তা তুমি ভাবছ না, কিন্তু মানুষের যা, তা-ই ভাবছ।”"},{"v":34,"ve":34,"vl":"34","bn":"এর পরে তিনি সাহাবীদের আর অন্য লোকদের তাঁর কাছে ডেকে বললেন, “যদি কেউ আমার পথে আসতে চায় তবে সে নিজের ইচ্ছামত না চলুক; নিজের ক্রুশ বয়ে নিয়ে সে আমার পিছনে আসুক।"},{"v":35,"ve":35,"vl":"35","bn":"যে কেউ তার নিজের জন্য বেঁচে থাকতে চায় সে তার সত্যিকারের জীবন হারাবে; কিন্তু যে কেউ আমার জন্য এবং আল্লাহ্‌র দেওয়া সুসংবাদের জন্য তার প্রাণ হারায়, সে তার সত্যিকারের জীবন রক্ষা করবে।"},{"v":36,"ve":36,"vl":"36","bn":"যদি কেউ সমস্ত দুনিয়া লাভ করে তার বিনিময়ে তার সত্যিকারের জীবন হারায় তবে তার কোন লাভ নেই,"},{"v":37,"ve":37,"vl":"37","bn":"কারণ সত্যিকারের জীবন ফিরে পাবার জন্য তার দেবার মত কি আছে?"},{"v":38,"ve":38,"vl":"38","bn":"এই কালের বেঈমান ও গুনাহ্‌গার লোকদের মধ্যে যদি কেউ আমাকে নিয়ে আর আমার কথা নিয়ে লজ্জাবোধ করে, তবে ইব্‌ন্তেআদম যখন পবিত্র ফেরেশতাদের সংগে করে তাঁর পিতার মহিমায় আসবেন, তখন তিনিও সেই লোকের সম্বন্ধে লজ্জাবোধ করবেন।”"}],"9":[{"v":1,"ve":1,"vl":"1","bn":"তারপর ঈসা সাহাবীদের বললেন, “আমি তোমাদের সত্যিই বলছি, এখানে এমন কয়েকজন আছে যাদের কাছে আল্লাহ্‌র রাজ্য মহাশক্তিতে দেখা না দেওয়া পর্যন্ত তারা কোনমতেই মারা যাবে না।”"},{"heading":"হযরত ঈসা রূহুল্লাহ্‌র নূরানী চেহারা","v":2,"ve":2,"vl":"2","bn":"এর ছয় দিন পরে ঈসা কেবল পিতর, ইয়াকুব ও ইউহোন্নাকে সংগে নিয়ে একটা উঁচু পাহাড়ে গেলেন। এই সাহাবীদের সামনে তাঁর চেহারা বদলে গেল।"},{"v":3,"ve":3,"vl":"3","bn":"তাঁর কাপড়-চোপড় এমন চোখ ঝলসানো সাদা হল যে, দুনিয়ার কোন ধোপার পক্ষে তেমন করে কাপড় কাচা সম্ভব নয়।"},{"v":4,"ve":4,"vl":"4","bn":"সাহাবীরা সেখানে নবী ইলিয়াস ও নবী মূসাকে দেখতে পেলেন। তাঁরা ঈসার সংগে কথা বলছিলেন।"},{"v":5,"ve":5,"vl":"5","bn":"তখন পিতর ঈসাকে বললেন, “হুজুর, ভালই হয়েছে যে, আমরা এখানে আছি। আমরা এখানে তিনটা কুঁড়ে-ঘর তৈরী করি- একটা আপনার, একটা মূসার ও একটা ইলিয়াসের জন্য।”"},{"v":6,"ve":6,"vl":"6","bn":"কি যে বলা উচিত তা পিতর বুঝলেন না, কারণ তাঁরা খুব ভয় পেয়েছিলেন।"},{"v":7,"ve":7,"vl":"7","bn":"এই সময় একটা মেঘ এসে তাঁদের ঢেকে ফেলল, আর সেই মেঘ থেকে এই কথা শোনা গেল, “ইনিই আমার প্রিয় পুত্র, তোমরা এঁর কথা শোন।”"},{"v":8,"ve":8,"vl":"8","bn":"সাহাবীরা তখনই চারদিকে তাকালেন কিন্তু ঈসা ছাড়া আর কাউকে দেখতে পেলেন না।"},{"v":9,"ve":9,"vl":"9","bn":"পরে পাহাড় থেকে নেমে আসবার সময় ঈসা তাঁদের হুকুম দিলেন, “তোমরা যা দেখলে তা ইব্‌ন্তেআদম মৃত্যু থেকে জীবিত হয়ে না ওঠা পর্যন্ত কাউকে বোলো না।”"},{"v":10,"ve":10,"vl":"10","bn":"সাহাবীরা ঈসার হুকুম পালন করলেন, কিন্তু মৃত্যু থেকে জীবিত হয়ে ওঠার অর্থ কি তা নিজেদের মধ্যে আলোচনা করতে লাগলেন।"},{"v":11,"ve":11,"vl":"11","bn":"তাঁরা ঈসাকে জিজ্ঞাসা করলেন, “আলেমেরা কেন বলেন প্রথমে ইলিয়াস নবীর আসা দরকার?”"},{"v":12,"ve":12,"vl":"12","bn":"জবাবে ঈসা তাঁদের বললেন, “এই কথা সত্যি যে, প্রথমে ইলিয়াস এসে সব কিছু আগের অবস্থায় ফিরিয়ে আনবেন। তবে ইব্‌ন্তেআদমের বিষয়ে কেমন করেই বা পাক-কিতাবে লেখা আছে যে, তাঁকে খুব কষ্টভোগ করতে হবে এবং লোকে তাঁকে অগ্রাহ্য করবে?"},{"v":13,"ve":13,"vl":"13","bn":"কিন্তু আমি তোমাদের বলছি, ইলিয়াসের বিষয়ে পাক-কিতাবে যা লেখা আছে সেইভাবে তিনি এসেছিলেন, আর লোকেরা তাঁর উপর যা ইচ্ছা তা-ই করেছে।”"},{"heading":"ভূতে পাওয়া ছেলেটিকে সুস্থ করা","v":14,"ve":14,"vl":"14","bn":"ঈসা ও সেই তিনজন সাহাবী অন্য সাহাবীদের কাছে ফিরে এসে দেখলেন, তাঁদের চারপাশে অনেক লোক জমায়েত হয়েছে এবং কয়েকজন আলেম তাঁদের সংগে তর্ক জুড়ে দিয়েছেন।"},{"v":15,"ve":15,"vl":"15","bn":"লোকেরা ঈসাকে দেখেই খুব আশ্চর্য হয়ে গেল এবং দৌড়ে গিয়ে তাঁকে সালাম জানাল।"},{"v":16,"ve":16,"vl":"16","bn":"ঈসা আলেমদের জিজ্ঞাসা করলেন, “আপনারা ওদের সংগে কি বিষয়ে তর্ক করছেন?”"},{"v":17,"ve":17,"vl":"17","bn":"ভিড়ের মধ্য থেকে একজন লোক জবাব দিল, “হুজুর, আমার ছেলেকে আপনার কাছে এনেছিলাম। তাকে বোবা ভূতে পেয়েছে।"},{"v":18,"ve":18,"vl":"18","bn":"সেই ভূত যখনই তাকে ধরে তখনই আছাড় দিয়ে মাটিতে ফেলে। তার মুখ থেকে ফেনা বের হয় আর সে দাঁতে দাঁত ঘষে এবং শক্ত হয়ে যায়। আমি আপনার সাহাবীদের সেই ভূতকে ছাড়িয়ে দিতে বললাম, কিন্তু তাঁরা পারলেন না।”"},{"v":19,"ve":19,"vl":"19","bn":"তখন ঈসা বললেন, “বেঈমান লোকেরা! আর কতদিন আমি তোমাদের সংগে থাকব? কতদিন তোমাদের সহ্য করব? ছেলেটিকে আমার কাছে আন।”"},{"v":20,"ve":20,"vl":"20","bn":"লোকেরা তখন ছেলেটিকে ঈসার কাছে আনল। তাঁকে দেখেই সেই ভূত ছেলেটিকে খুব জোরে মুচড়ে ধরল। ছেলেটি মুখ থেকে ফেনা বের করতে করতে মাটিতে গড়াগড়ি দিতে লাগল।"},{"v":21,"ve":21,"vl":"21","bn":"ঈসা তার বাবাকে জিজ্ঞাসা করলেন, “কতদিন হল তার এই রকম হয়েছে?” লোকটি বলল, “ছেলেবেলা থেকে।"},{"v":22,"ve":22,"vl":"22","bn":"এই ভূত তাকে মেরে ফেলবার জন্য প্রায়ই আগুনে আর পানিতে ফেলে দিয়েছে। তবে আপনি যদি আমাদের কোন উপকার করতে পারেন তবে দয়া করে তা করুন।”"},{"v":23,"ve":23,"vl":"23","bn":"ঈসা তাকে বললেন, “‘যদি করতে পারেন,’ এই কথার মানে কি? যে বিশ্বাস করে তার জন্য সব কিছুই সম্ভব।”"},{"v":24,"ve":24,"vl":"24","bn":"তখনই ছেলেটির বাবা চিৎকার করে বলল, “আমি বিশ্বাস করছি; আমার মধ্যে এখনও যে অবিশ্বাস আছে তা দূর করে দিন।”"},{"v":25,"ve":25,"vl":"25","bn":"অনেক লোক দৌড়ে আসছে দেখে ঈসা সেই ভূতকে ধমক দিয়ে বললেন, “ওহে বধির ও বোবা ভূত, আমি তোমাকে হুকুম দিচ্ছি, এর মধ্য থেকে বের হও; আর কখনও এর মধ্যে ঢুকো না।”"},{"v":26,"ve":26,"vl":"26","bn":"তখন সেই ভূত চিৎকার করে ছেলেটাকে জোরে মুচড়ে ধরল এবং তার মধ্য থেকে বের হয়ে গেল। তাতে ছেলেটি মরার মত পড়ে রইল দেখে অনেকে বলল, “ও মারা গেছে।”"},{"v":27,"ve":27,"vl":"27","bn":"ঈসা কিন্তু তার হাত ধরে তুললে পর সে উঠে দাঁড়াল।"},{"v":28,"ve":28,"vl":"28","bn":"এর পরে ঈসা ঘরের ভিতরে গেলেন। তখন সাহাবীরা গোপনে তাঁকে জিজ্ঞাসা করলেন, “আমরা তাকে ছাড়াতে পারলাম না কেন?”"},{"v":29,"ve":29,"vl":"29","bn":"ঈসা বললেন, “মুনাজাত ছাড়া আর কোন মতেই এই রকম ভূত ছাড়ানো যায় না।”"},{"v":30,"ve":30,"vl":"30","bn":"পরে তাঁরা সেই জায়গা ছেড়ে গালীল প্রদেশের মধ্য দিয়ে চলে গেলেন। তিনি চেয়েছিলেন যেন কেউ জানতে না পারে যে, তিনি কোথায় যাচ্ছেন,"},{"v":31,"ve":31,"vl":"31","bn":"কারণ তখন তিনি তাঁর সাহাবীদের শিক্ষা দিচ্ছিলেন। তিনি তাঁদের বলছিলেন, “ইব্‌ন্তেআদমকে লোকদের হাতে ধরিয়ে দেওয়া হবে। তারা তাঁকে হত্যা করবে এবং তিন দিনের দিন আবার তিনি জীবিত হয়ে উঠবেন।”"},{"v":32,"ve":32,"vl":"32","bn":"সাহাবীরা কিন্তু তাঁর কথার মানে বুঝতে পারলেন না এবং তাঁকে জিজ্ঞাসা করতেও তাঁদের ভয় হল।"},{"heading":"বড় কে?","v":33,"ve":33,"vl":"33","bn":"তারপর ঈসা ও তাঁর সাহাবীরা কফরনাহূমে গেলেন। তিনি ঘরের মধ্যে গিয়ে সাহাবীদের জিজ্ঞাসা করলেন, “তোমরা পথে কি নিয়ে তর্ক করছিলে?”"},{"v":34,"ve":34,"vl":"34","bn":"সাহাবীরা চুপ করে রইলেন, কারণ কে সবচেয়ে বড় তা নিয়ে পথে তাঁরা তর্কাতর্কি করছিলেন।"},{"v":35,"ve":35,"vl":"35","bn":"ঈসা বসলেন এবং সেই বারোজন সাহাবীকে নিজের কাছে ডেকে বললেন, “কেউ যদি প্রধান হতে চায় তবে তাকে সবার শেষে থাকতে হবে এবং সকলের সেবাকারী হতে হবে।”"},{"v":36,"ve":36,"vl":"36","bn":"পরে তিনি একটা শিশুকে নিয়ে সাহাবীদের সামনে দাঁড় করালেন। তাকে কোলে নিয়ে তিনি বললেন,"},{"v":37,"ve":37,"vl":"37","bn":"“যে কেউ আমার নামে এর মত কোন শিশুকে গ্রহণ করে সে আমাকেই গ্রহণ করে, আর যে আমাকে গ্রহণ করে সে কেবল আমাকে গ্রহণ করে না, কিন্তু যিনি আমাকে পাঠিয়েছেন তাঁকেই গ্রহণ করে।”"},{"heading":"পক্ষে না বিপক্ষে?","v":38,"ve":38,"vl":"38","bn":"ইউহোন্না ঈসাকে বললেন, “হুজুর, আমরা একজন লোককে আপনার নামে ভূত ছাড়াতে দেখে তাকে নিষেধ করলাম, কারণ সে আমাদের দলের লোক নয়।”"},{"v":39,"ve":39,"vl":"39","bn":"ঈসা বললেন, “তাকে নিষেধ কোরো না। আমার নামে অলৌকিক কাজ করবার পরে কেউ ফিরে আমার নিন্দা করতে পারে না,"},{"v":40,"ve":40,"vl":"40","bn":"কারণ যে আমাদের বিপক্ষে থাকে না সে তো আমাদের পক্ষেই আছে।"},{"v":41,"ve":41,"vl":"41","bn":"আমি তোমাদের সত্যিই বলছি, তোমরা মসীহের লোক বলে যে কেউ তোমাদের এক পেয়ালা পানি খেতে দেয় সে কোনমতে তার পুরস্কার হারাবে না।"},{"heading":"গুনাহ্‌ করাবার বিষয়ে","v":42,"ve":42,"vl":"42","bn":"“আমার উপর ঈমানদার এই ছোটদের মধ্যে কাউকে যদি কেউ গুনাহের পথে নিয়ে যায় তবে তার গলায় একটা বড় পাথর বেঁধে তাকে সাগরে ফেলে দেওয়া বরং তার পক্ষে ভাল।"},{"v":43,"ve":43,"vl":"43","bn":"তোমার হাত যদি তোমাকে গুনাহের পথে টানে তবে"},{"v":44,"ve":44,"vl":"44","bn":"তা কেটে ফেলে দাও। দুই হাত নিয়ে জাহান্নামে যাবার চেয়ে বরং নুলা হয়ে জীবনে ঢোকা তোমার পক্ষে ভাল।"},{"v":45,"ve":46,"vl":"45-46","bn":"সেই জাহান্নামের আগুন কখনও নেভে না। যদি তোমার পা তোমাকে গুনাহের পথে টানে তবে তা কেটে ফেলে দাও। দুই পা নিয়ে জাহান্নামে পড়বার চেয়ে বরং খোঁড়া হয়ে জীবনে ঢোকা তোমার পক্ষে ভাল।"},{"v":47,"ve":47,"vl":"47","bn":"তোমার চোখ যদি তোমাকে গুনাহের পথে টানে তবে তা তুলে ফেল। দুই চোখ নিয়ে জাহান্নামে পড়বার চেয়ে বরং কানা হয়ে আল্লাহ্‌র রাজ্যে ঢোকা তোমার পক্ষে ভাল।"},{"v":48,"ve":48,"vl":"48","bn":"সেই জাহান্নামে মরা মানুষের গোশ্‌ত খাওয়া পোকারা কখনও মরে না, আর সেখানকার আগুন কখনও নেভে না।"},{"v":49,"ve":49,"vl":"49","bn":"“লবণ দেওয়ার মত প্রত্যেকের উপর আগুন দেওয়া হবে।"},{"v":50,"ve":50,"vl":"50","bn":"“লবণ ভাল জিনিস, কিন্তু যদি লবণের স্বাদ নষ্ট হয়ে যায় তবে তা কেমন করে আবার নোনতা করা যাবে? তোমাদের অন্তরের মধ্যে লবণ রাখ এবং তোমরা একে অন্যের সংগে শান্তিতে থাক।”"}],"10":[{"heading":"স্ত্রী তালাকের বিষয়ে শিক্ষা","v":1,"ve":1,"vl":"1","bn":"পরে ঈসা সেই জায়গা ছেড়ে এহুদিয়া প্রদেশে এবং জর্ডান নদীর অন্য পারে গেলেন। অনেক লোক আবার তাঁর কাছে এসে জমায়েত হল। তখন তিনি তাঁর নিয়ম মতই লোকদের শিক্ষা দিতে লাগলেন।"},{"v":2,"ve":2,"vl":"2","bn":"এই সময় কয়েকজন ফরীশী এসে তাঁকে পরীক্ষা করবার জন্য বললেন, “মূসার শরীয়ত মতে স্ত্রীকে তালাক দেওয়া কি কারও পক্ষে উচিত?”"},{"v":3,"ve":3,"vl":"3","bn":"ঈসা তাঁদের বললেন, “মূসা আপনাদের কি হুকুম দিয়েছেন?”"},{"v":4,"ve":4,"vl":"4","bn":"তাঁরা বললেন, “তিনি তালাক-নামা লিখে স্ত্রীকে তালাক দেবার অনুমতি দিয়েছেন।”"},{"v":5,"ve":5,"vl":"5","bn":"ঈসা বললেন, “আপনাদের মন কঠিন বলেই মূসা এই হুকুম লিখেছিলেন।"},{"v":6,"ve":6,"vl":"6","bn":"কিন্তু এ-ও লেখা আছে যে, সৃষ্টির শুরুতে ‘আল্লাহ্‌ তাদের পুরুষ ও স্ত্রীলোক করে সৃষ্টি করেছিলেন।"},{"v":7,"ve":7,"vl":"7","bn":"এইজন্যই মানুষ পিতা-মাতাকে ছেড়ে তার স্ত্রীর সংগে এক হয়ে থাকবে,"},{"v":8,"ve":8,"vl":"8","bn":"আর তারা দু’জন এক শরীর হবে।’ সেইজন্য তারা আর দুই নয়, কিন্তু এক শরীর।"},{"v":9,"ve":9,"vl":"9","bn":"তাহলে আল্লাহ্‌ যা একসংগে যোগ করেছেন মানুষ তা আলাদা না করুক।”"},{"v":10,"ve":10,"vl":"10","bn":"এর পরে তাঁরা ঘরে ঢুকলেন আর সাহাবীরা ঈসাকে আবার সেই বিষয়ে জিজ্ঞাসা করলেন।"},{"v":11,"ve":11,"vl":"11","bn":"তখন তিনি তাঁদের বললেন, “যে কেউ নিজের স্ত্রীকে তালাক দিয়ে অন্য স্ত্রীলোককে বিয়ে করে সে তার স্ত্রীর বিরুদ্ধে জেনা করে।"},{"v":12,"ve":12,"vl":"12","bn":"আর স্ত্রী যদি স্বামীকে তালাক দিয়ে অন্য লোককে বিয়ে করে তবে সেও জেনা করে।”"},{"heading":"হযরত ঈসা মসীহ্‌ ও ছেলেমেয়েরা","v":13,"ve":13,"vl":"13","bn":"পরে লোকেরা ছোট ছোট ছেলেমেয়েদের ঈসার কাছে নিয়ে আসল যেন তিনি তাদের উপর হাত রাখেন। কিন্তু সাহাবীরা সেই লোকদের বকুনি দিতে লাগলেন।"},{"v":14,"ve":14,"vl":"14","bn":"ঈসা তা দেখে অসন্তুষ্ট হয়ে সাহাবীদের বললেন, “ছেলেমেয়েদের আমার কাছে আসতে দাও, বাধা দিয়ো না; কারণ আল্লাহ্‌র রাজ্য এদের মত লোকদেরই।"},{"v":15,"ve":15,"vl":"15","bn":"আমি তোমাদের সত্যি বলছি, ছোট ছেলেমেয়ের মত করে আল্লাহ্‌র শাসন মেনে না নিলে কেউ কোনমতেই আল্লাহ্‌র রাজ্যে ঢুকতে পারবে না।”"},{"v":16,"ve":16,"vl":"16","bn":"তারপর ঈসা সেই ছেলেমেয়েদের কোলে নিলেন এবং তাদের মাথায় হাত রেখে দোয়া করলেন।"},{"heading":"একজন ধনী লোক","v":17,"ve":17,"vl":"17","bn":"ঈসা আবার যখন পথে বের হলেন তখন একজন লোক দৌড়ে তাঁর কাছে আসল এবং তাঁর সামনে হাঁটু পেতে বলল, “হে ওস্তাদ, আপনি একজন ভাল লোক। আমাকে বলুন, অনন্ত জীবন লাভ করবার জন্য আমি কি করব?”"},{"v":18,"ve":18,"vl":"18","bn":"ঈসা তাকে বললেন, “আমাকে ভাল বলছ কেন? আল্লাহ্‌ ছাড়া আর কেউই ভাল নয়।"},{"v":19,"ve":19,"vl":"19","bn":"তুমি তো হুকুমগুলো জান্ত ‘খুন কোরো না, জেনা কোরো না, চুরি কোরো না, মিথ্যা সাক্ষ্য দিয়ো না, ঠকিয়ো না, পিতা-মাতাকে সম্মান কোরো।’ ”"},{"v":20,"ve":20,"vl":"20","bn":"লোকটি ঈসাকে বলল, “ওস্তাদ, ছোটবেলা থেকে আমি এই সব পালন করে আসছি।”"},{"v":21,"ve":21,"vl":"21","bn":"এতে ঈসা তার দিকে চেয়ে দেখলেন এবং মহব্বতে পূর্ণ হয়ে তাকে বললেন, “একটা জিনিস তোমার বাকী আছে। যাও, তোমার যা কিছু আছে তা বিক্রি করে গরীবদের দান কর। তাতে তুমি বেহেশতে ধন পাবে। তার পরে এসে আমার উম্মত হও।”"},{"v":22,"ve":22,"vl":"22","bn":"এই কথা শুনে লোকটির মুখ ্নান হয়ে গেল। তার অনেক ধন-সম্পত্তি ছিল বলে সে দুঃখিত হয়ে চলে গেল।"},{"v":23,"ve":23,"vl":"23","bn":"তখন ঈসা চারদিকে তাকিয়ে তাঁর সাহাবীদের বললেন, “ধনীদের পক্ষে আল্লাহ্‌র রাজ্যে ঢোকা কত কঠিন!”"},{"v":24,"ve":24,"vl":"24","bn":"সাহাবীরা তাঁর কথা শুনে আশ্চর্য হলেন। ঈসা আবার বললেন, “সন্তানেরা, যারা ধন-সম্পদের উপর নির্ভর করে তাদের পক্ষে আল্লাহ্‌র রাজ্যে ঢোকা কত কঠিন।"},{"v":25,"ve":25,"vl":"25","bn":"ধনীর পক্ষে আল্লাহ্‌র রাজ্যে ঢুকবার চেয়ে বরং সূচের ফুটা দিয়ে উটের যাওয়া সহজ।”"},{"v":26,"ve":26,"vl":"26","bn":"এতে সাহাবীরা আরও আশ্চর্য হয়ে নিজেদের মধ্যে বলাবলি করতে লাগলেন, “তাহলে কে নাজাত পেতে পারে?”"},{"v":27,"ve":27,"vl":"27","bn":"ঈসা তাঁদের দিকে তাকিয়ে বললেন, “মানুষের পক্ষে এটা অসম্ভব বটে, কিন্তু আল্লাহ্‌র পক্ষে অসম্ভব নয়; তাঁর পক্ষে সবই সম্ভব।”"},{"v":28,"ve":28,"vl":"28","bn":"পিতর তাঁকে বললেন, “দেখুন, আমরা তো সব কিছু ছেড়ে দিয়ে আপনার সাহাবী হয়েছি।”"},{"v":29,"ve":29,"vl":"29","bn":"জবাবে ঈসা বললেন, “আমি তোমাদের সত্যিই বলছি, যে কেউ আমার জন্য ও আল্লাহ্‌র দেওয়া সুসংবাদের জন্য বাড়ী-ঘর, ভাই-বোন, মা-বাবা, ছেলে-মেয়ে ও জায়গা-জমি ছেড়ে দিয়েছে,"},{"v":30,"ve":30,"vl":"30","bn":"সে এই যুগেই তার একশো গুণ বেশী বাড়ী-ঘর, ভাই-বোন, মা, ছেলে-মেয়ে ও জায়গা-জমি পাবে এবং সংগে সংগে অত্যাচারও ভোগ করবে; আর আগামী যুগে সে অনন্ত জীবন লাভ করবে।"},{"v":31,"ve":31,"vl":"31","bn":"কিন্তু যারা প্রথম সারিতে আছে তাদের মধ্যে অনেকে শেষে পড়বে, আর যারা শেষ সারিতে আছে তাদের মধ্যে অনেকে প্রথম হবে।”"},{"heading":"আবার হযরত ঈসা মসীহের মৃত্যুর কথা","v":32,"ve":32,"vl":"32","bn":"এর পরে ঈসা ও তাঁর সাহাবীরা জেরুজালেমের পথে চললেন। ঈসা তাঁদের আগে আগে হাঁটছিলেন; সাহাবীরা অবাক হয়ে তাঁর সংগে যাচ্ছিলেন এবং যে লোকেরা পিছনে আসছিল তারা ভয়ে ভয়ে হাঁটছিল। ঈসা আবার তাঁর বারোজন সাহাবীকে একপাশে ডেকে নিয়ে গিয়ে নিজের উপর কি হতে যাচ্ছে তা তাঁদের বলতে লাগলেন।"},{"v":33,"ve":33,"vl":"33","bn":"তিনি বললেন, “দেখ, আমরা জেরুজালেমে যাচ্ছি। সেখানে ইব্‌ন্তেআদমকে প্রধান ইমামদের ও আলেমদের হাতে ধরিয়ে দেওয়া হবে। তাঁরা তাঁর বিচার করে তাঁকে মৃত্যুর উপযুক্ত বলে স্থির করবেন এবং অ-ইহুদীদের হাতে দেবেন।"},{"v":34,"ve":34,"vl":"34","bn":"অ-ইহুদীরা তাঁকে ঠাট্টা-বিদ্রূপ করবে, তাঁর গায়ে থুথু দেবে, তাঁকে ভীষণভাবে চাবুক মারবে এবং হত্যা করবে। তিন দিনের দিন আবার তিনি জীবিত হয়ে উঠবেন।”"},{"heading":"হযরত ইয়াকুব ও হযরত ইউহোন্নার অনুরোধ","v":35,"ve":35,"vl":"35","bn":"পরে সিবদিয়ের ছেলে ইয়াকুব ও ইউহোন্না ঈসার কাছে এসে বললেন, “হুজুর, আমাদের ইচ্ছা এই যে, আমরা যা চাইব আমাদের জন্য আপনি তা-ই করবেন।”"},{"v":36,"ve":36,"vl":"36","bn":"ঈসা বললেন, “তোমাদের জন্য আমি কি করব? তোমরা কি চাও?”"},{"v":37,"ve":37,"vl":"37","bn":"তাঁরা বললেন, “আপনি যখন মহিমার সংগে রাজত্ব করবেন তখন যেন আমাদের একজন আপনার ডানপাশে ও অন্যজন বাঁপাশে বসতে পারে।”"},{"v":38,"ve":38,"vl":"38","bn":"ঈসা বললেন, “তোমরা কি চাইছ তা জান না। যে দুঃখের পেয়ালায় আমি খেতে যাচ্ছি তাতে কি তোমরা খেতে পার? কিংবা যে তরিকাবন্দী আমি নিতে যাচ্ছি তা কি তোমরা নিতে পার?”"},{"v":39,"ve":39,"vl":"39","bn":"তাঁরা বললেন, “জ্বী, পারি।” তখন ঈসা তাঁদের বললেন, “যে দুঃখের পেয়ালায় আমি খাব তোমরা অবশ্য তাতে খাবে, আর যে তরিকাবন্দী আমি নেব তা তোমরাও নেবে,"},{"v":40,"ve":40,"vl":"40","bn":"কিন্তু আমার ডান বা বাঁপাশে বসতে দেবার অধিকার আমার নেই। ঐ জায়গাগুলো যাদের জন্য ঠিক করা আছে তারাই তা পাবে।”"},{"v":41,"ve":41,"vl":"41","bn":"বাকী দশজন সাহাবী এই সব কথা শুনে ইয়াকুব ও ইউহোন্নার উপর বিরক্ত হলেন।"},{"v":42,"ve":42,"vl":"42","bn":"তখন ঈসা সবাইকে একসংগে ডেকে বললেন, “তোমরা জান যে, অ-ইহুদীদের শাসনকর্তারা অ-ইহুদীদের প্রভু হয় এবং তাদের নেতারা তাদের উপর হুকুম চালায়।"},{"v":43,"ve":43,"vl":"43","bn":"কিন্তু তোমাদের মধ্যে তা হওয়া উচিত নয়, বরং তোমাদের মধ্যে যে বড় হতে চায় তাকে তোমাদের সেবাকারী হতে হবে,"},{"v":44,"ve":44,"vl":"44","bn":"আর যে প্রথম হতে চায় তাকে সকলের গোলাম হতে হবে।"},{"v":45,"ve":45,"vl":"45","bn":"মনে রেখো, ইব্‌ন্তেআদম সেবা পেতে আসেন নি বরং সেবা করতে এসেছেন এবং অনেক লোকের মুক্তির মূল্য হিসাবে তাদের প্রাণের পরিবর্তে নিজের প্রাণ দিতে এসেছেন।”"},{"heading":"অন্ধ বরতীময় সুস্থ হল","v":46,"ve":46,"vl":"46","bn":"পরে ঈসা ও তাঁর সাহাবীরা জেরিকো শহরে গেলেন। যখন তিনি সাহাবীদের ও অনেক লোকের সংগে শহর থেকে চলে যাচ্ছিলেন তখন তীময়ের ছেলে বরতীময় নামে একজন অন্ধ ভিখারী পথের পাশে বসে ছিল।"},{"v":47,"ve":47,"vl":"47","bn":"“উনি নাসরত গ্রামের ঈসা,” এই কথা শুনে সে চিৎকার করে বলতে লাগল, “দাউদের বংশধর ঈসা, আমাকে দয়া করুন।”"},{"v":48,"ve":48,"vl":"48","bn":"এতে অনেকে তাকে ধমক দিয়ে চুপ করতে বলল, কিন্তু সে আরও চিৎকার করে বলল, “দাউদের বংশধর, আমাকে দয়া করুন।”"},{"v":49,"ve":49,"vl":"49","bn":"ঈসা থেমে বললেন, “ওকে ডাক।” লোকেরা অন্ধ লোকটিকে ডেকে বলল, “ভয় নেই, ওঠো। উনি তোমাকে ডাকছেন।”"},{"v":50,"ve":50,"vl":"50","bn":"তখন সে তার গায়ের চাদরটা ফেলে লাফ দিয়ে উঠল এবং ঈসার কাছে গেল।"},{"v":51,"ve":51,"vl":"51","bn":"ঈসা তাকে জিজ্ঞাসা করলেন, “আমি তোমার জন্য কি করব? তুমি কি চাও?” অন্ধ লোকটি বলল, “হুজুর, আমি যেন দেখতে পাই।”"},{"v":52,"ve":52,"vl":"52","bn":"ঈসা বললেন, “যাও, তুমি ঈমান এনেছ বলে ভাল হয়েছ।” তাতে লোকটি তখনই দেখতে পেল এবং পথ দিয়ে ঈসার পিছনে পিছনে চলতে লাগল।"}],"11":[{"heading":"জেরুজালেমে প্রবেশ","v":1,"ve":1,"vl":"1","bn":"তাঁরা জেরুজালেমের কাছাকাছি পৌঁছে জৈতুন পাহাড়ের গায়ে বৈৎফগী ও বেথানিয়া গ্রামের কাছে আসলেন। সেখানে পৌঁছে ঈসা তাঁর দু’জন সাহাবীকে এই বলে পাঠিয়ে দিলেন,"},{"v":2,"ve":2,"vl":"2","bn":"“তোমরা ঐ সামনের গ্রামে যাও। গ্রামে ঢুকবার সময় দেখতে পাবে একটা গাধার বাচ্চা সেখানে বাঁধা আছে। তার উপরে কেউ কখনও চড়ে নি।"},{"v":3,"ve":3,"vl":"3","bn":"তোমরা ওটা খুলে এখানে নিয়ে এস। যদি কেউ তোমাদের জিজ্ঞাসা করে, ‘কেন তোমরা এটা করছ?’ তবে বোলো, ‘হুজুরের দরকার আছে; তিনি ওটাকে তাড়াতাড়ি করে ফিরিয়ে দেবেন।’ ”"},{"v":4,"ve":4,"vl":"4","bn":"তখন তাঁরা গিয়ে দেখলেন গাধার বাচ্চাটা রাস্তার উপর ঘরের দরজার কাছে বাঁধা আছে। তাঁরা যখন গাধাটার বাঁধন খুলছিলেন,"},{"v":5,"ve":5,"vl":"5","bn":"তখন যারা সেখানে দাঁড়িয়ে ছিল তারা বলল, “তোমরা কি করছ? গাধার বাচ্চাটা খুলছ কেন?”"},{"v":6,"ve":6,"vl":"6","bn":"ঈসা যা বলতে বলেছিলেন সাহাবীরা লোকদের তা-ই বললেন। তখন লোকেরা গাধাটা নিয়ে যেতে দিল।"},{"v":7,"ve":7,"vl":"7","bn":"তাঁরা সেই গাধার বাচ্চাটা ঈসার কাছে এনে তার উপর তাঁদের গায়ের চাদর পেতে দিলেন। ঈসা তার উপরে বসলেন।"},{"v":8,"ve":8,"vl":"8","bn":"অনেক লোক তাদের গায়ের চাদর রাস্তার উপরে বিছিয়ে দিল, আর অন্যেরা মাঠের গাছপালা থেকে পাতা সুদ্ধ ডাল কেটে এনে পথে ছড়িয়ে দিল।"},{"v":9,"ve":9,"vl":"9","bn":"যারা ঈসার সামনে ও পিছনে যাচ্ছিল তারা চিৎকার করে বলতে লাগল, “মারহাবা! মাবুদের নামে যিনি আসছেন তাঁর প্রশংসা হোক।"},{"v":10,"ve":10,"vl":"10","bn":"আমাদের পিতা দাউদের যে রাজ্য আসছে তার প্রশংসা হোক। বেহেশতেও মারহাবা!”"},{"v":11,"ve":11,"vl":"11","bn":"ঈসা জেরুজালেমে গিয়ে বায়তুল-মোকাদ্দসে ঢুকলেন এবং চারদিকের সব কিছুই লক্ষ্য করলেন, কিন্তু বেলা গিয়েছিল বলে তাঁর বারোজন সাহাবীকে নিয়ে তিনি বেথানিয়াতে চলে গেলেন।"},{"heading":"বায়তুল-মোকাদ্দসে হযরত ঈসা মসীহ্‌","v":12,"ve":12,"vl":"12","bn":"পরের দিন যখন তাঁরা বেথানিয়া ছেড়ে যাচ্ছিলেন তখন ঈসার খিদে পেল।"},{"v":13,"ve":13,"vl":"13","bn":"তখন ডুমুর ফল পাকবার সময় ছিল না, কিন্তু তবুও তিনি দূর থেকে পাতায় ঢাকা একটা ডুমুর গাছ দেখে তাতে কোন ফল আছে কিনা তা দেখতে গেলেন। কাছে গিয়ে তিনি তাতে পাতা ছাড়া আর কিছুই দেখতে পেলেন না।"},{"v":14,"ve":14,"vl":"14","bn":"সেইজন্য তিনি সেই গাছটাকে বললেন, “আর কখনও কেউ যেন তোমার ফল না খায়।” সাহাবীরা তাঁর এই কথা শুনতে পেলেন।"},{"v":15,"ve":15,"vl":"15","bn":"জেরুজালেমে পৌঁছে ঈসা বায়তুল-মোকাদ্দসে ঢুকলেন এবং সেখানে যারা বেচা-কেনা করছিল তাদের তাড়িয়ে দিলেন। তিনি টাকা বদল করে দেবার লোকদের টেবিল ও যারা কবুতর বিক্রি করছিল তাদের বসবার জায়গা উল্টে ফেললেন।"},{"v":16,"ve":16,"vl":"16","bn":"বায়তুল-মোকাদ্দসের উঠানের মধ্য দিয়ে তিনি কোন বেচা-কেনার জিনিস নিয়ে যেতে দিলেন না।"},{"v":17,"ve":17,"vl":"17","bn":"পরে শিক্ষা দেবার সময় তিনি সেই লোকদের বললেন, “কিতাবে কি এই কথা লেখা নেই যে, ‘আমার ঘরকে সমস্ত জাতির মুনাজাতের ঘর বলা হবে’? কিন্তু তোমরা এটাকে ডাকাতের আড্ডাখানা করে তুলেছ!”"},{"v":18,"ve":18,"vl":"18","bn":"প্রধান ইমামেরা ও আলেমেরা এই কথা শুনে ঈসাকে হত্যা করবার উপায় খুঁজতে লাগলেন। তাঁরা তাঁকে ভয় করতেন, কারণ লোকেরা তাঁর শিক্ষায় আশ্চর্য হয়ে গিয়েছিল।"},{"v":19,"ve":19,"vl":"19","bn":"সন্ধ্যা হলে পর সাহাবীদের নিয়ে তিনি শহরের বাইরে চলে গেলেন।"},{"heading":"সেই ডুমুর গাছটা","v":20,"ve":20,"vl":"20","bn":"সকালবেলায় সেই পথ দিয়ে আসবার সময় সাহাবীরা দেখলেন সেই ডুমুর গাছটা শিকড়সুদ্ধ শুকিয়ে গেছে।"},{"v":21,"ve":21,"vl":"21","bn":"ঈসার কথা মনে করে পিতর ঈসাকে বললেন, “হুজুর, দেখুন, যে ডুমুর গাছটাকে আপনি বদদোয়া দিয়েছিলেন সেটা শুকিয়ে গেছে।”"},{"v":22,"ve":22,"vl":"22","bn":"তখন ঈসা বললেন, “আল্লাহ্‌র উপরে বিশ্বাস রাখ।"},{"v":23,"ve":23,"vl":"23","bn":"আমি তোমাদের সত্যিই বলছি, যদি কেউ অন্তরে কোন সন্দেহ না রেখে এই পাহাড়টাকে বলে, ‘উঠে সাগরে গিয়ে পড়,’ আর বিশ্বাস করে যে, সে যা বলল তা-ই হবে, তবে তার জন্য তা-ই করা হবে।"},{"v":24,"ve":24,"vl":"24","bn":"সেইজন্য আমি তোমাদের বলছি, মুনাজাতের মধ্যে তোমরা যা কিছু চাও, বিশ্বাস কোরো তোমরা তা পেয়েছ, আর তোমাদের জন্য তা-ই হবে।"},{"v":25,"ve":26,"vl":"25-26","bn":"তোমরা যখন মুনাজাত কর তখন কারও বিরুদ্ধে যদি তোমাদের কোন কথা থাকে তবে তাকে মাফ কোরো, যেন তোমাদের বেহেশতী পিতা তোমাদেরও গুনাহ্‌ মাফ করতে পারেন।”"},{"heading":"হযরত ঈসা মসীহ্‌ কার অধিকারে কাজ করেন?","v":27,"ve":27,"vl":"27","bn":"পরে ঈসা ও তাঁর সাহাবীরা আবার জেরুজালেমে গেলেন। তিনি বায়তুল-মোকাদ্দসে হেঁটে বেড়াচ্ছেন এমন সময় প্রধান ইমামেরা, আলেমেরা ও বৃদ্ধ নেতারা তাঁর কাছে এসে জিজ্ঞাসা করলেন,"},{"v":28,"ve":28,"vl":"28","bn":"“তুমি কোন্‌ অধিকারে এই সব করছ? কে তোমাকে এই অধিকার দিয়েছে?”"},{"v":29,"ve":29,"vl":"29","bn":"জবাবে ঈসা বললেন, “আমি আপনাদের একটা কথা জিজ্ঞাসা করব। আপনারা যদি আমাকে উত্তর দিতে পারেন তবে আমিও আপনাদের বলব আমি কোন্‌ অধিকারে এই সব করছি।"},{"v":30,"ve":30,"vl":"30","bn":"বলুন দেখি, তরিকাবন্দী দেবার অধিকার ইয়াহিয়া আল্লাহ্‌র কাছ থেকে পেয়েছিলেন, না মানুষের কাছ থেকে পেয়েছিলেন?”"},{"v":31,"ve":31,"vl":"31","bn":"তখন তাঁরা নিজেদের মধ্যে এই আলোচনা করলেন, “আমরা যদি বলি, ‘আল্লাহ্‌র কাছ থেকে,’ তাহলে সে বলবে, ‘তবে আপনারা তাঁকে বিশ্বাস করেন নি কেন?’"},{"v":32,"ve":32,"vl":"32","bn":"আবার যদি বলি, ‘মানুষের কাছ থেকে,’ তবে?” তাঁরা লোকদের ভয় করতেন, কারণ সবাই ইয়াহিয়াকে সত্যিই একজন নবী বলে মনে করত।"},{"v":33,"ve":33,"vl":"33","bn":"সেইজন্য তাঁরা বললেন, “আমরা জানি না।” তখন ঈসা বললেন, “তাহলে আমিও আপনাদের বলব না আমি কোন্‌ অধিকারে এই সব করছি।”"}],"12":[{"heading":"আংগুর ক্ষেতের চাষীদের গল্প","v":1,"ve":1,"vl":"1","bn":"এর পর ঈসা গল্পের মধ্য দিয়ে তাঁদের কাছে শিক্ষা দিতে লাগলেন। তিনি বললেন, “একজন লোক একটা আংগুর ক্ষেত করে তার চারদিকে বেড়া দিলেন। পরে তিনি আংগুর-রস করবার জন্য একটা গর্ত খুঁড়লেন এবং একটা উঁচু পাহারা-ঘর তৈরী করলেন। পরে তিনি কয়েকজন চাষীর কাছে ক্ষেতটা ইজারা দিয়ে বিদেশে চলে গেলেন।"},{"v":2,"ve":2,"vl":"2","bn":"ফল পাকবার সময়ে তিনি সেই ফলের ভাগ নিয়ে আসবার জন্য একজন গোলামকে সেই চাষীদের কাছে পাঠিয়ে দিলেন।"},{"v":3,"ve":3,"vl":"3","bn":"কিন্তু সেই চাষীরা সেই গোলামকে ধরে মারল এবং খালি হাতে পাঠিয়ে দিল।"},{"v":4,"ve":4,"vl":"4","bn":"তখন মালিক আর একজন গোলামকে তাদের কাছে পাঠালেন। চাষীরা তার মাথায় আঘাত করল এবং তার সংগে খুব খারাপ ব্যবহার করল।"},{"v":5,"ve":5,"vl":"5","bn":"তিনি তবুও আর একজনকে পাঠালেন। তাকে চাষীরা মেরে ফেলল। পরে তিনি আরও অনেকজনকে পাঠালেন, কিন্তু তাদের মধ্যে কয়েকজনকে তারা মারধর করল আর অন্যদের মেরেই ফেলল।"},{"v":6,"ve":6,"vl":"6","bn":"“সেখানে পাঠাতে মালিকের মাত্র আর একজন বাকী ছিল। সে ছিল তাঁর প্রিয় পুত্র। তিনি সব শেষে পুত্রটিকে পাঠিয়ে দিলেন; ভাবলেন, ‘তারা অন্ততঃ আমার ছেলেকে সম্মান করবে।’"},{"v":7,"ve":7,"vl":"7","bn":"কিন্তু সেই চাষীরা নিজেদের মধ্যে বলাবলি করতে লাগল, ‘এ-ই তো পরে সম্পত্তির মালিক হবে। চল, আমরা ওকে মেরে ফেলি, তাহলে আমরাই সম্পত্তির মালিক হব।’"},{"v":8,"ve":8,"vl":"8","bn":"তারা ছেলেটিকে ধরে মেরে ফেলল এবং আংগুর ক্ষেতের বাইরে ফেলে দিল।"},{"v":9,"ve":9,"vl":"9","bn":"“তাহলে বলুন দেখি, আংগুর ক্ষেতের মালিক কি করবেন? তিনি এসে সেই চাষীদের মেরে ফেলবেন এবং আংগুর ক্ষেতটা অন্যদের হাতে দেবেন।"},{"v":10,"ve":10,"vl":"10","bn":"আপনারা কি পাক-কিতাবে পড়েন নি, ‘রাজমিস্ত্রিরা যে পাথরটা বাতিল করে দিয়েছিল সেটাই সবচেয়ে দরকারী পাথর হয়ে উঠল;"},{"v":11,"ve":11,"vl":"11","bn":"মাবুদই এটা করলেন, আর তা আমাদের চোখে খুব আশ্চর্য লাগে’?”"},{"v":12,"ve":12,"vl":"12","bn":"তখন সেই ধর্ম-নেতারা ঈসাকে ধরতে চাইলেন, কারণ তাঁরা বুঝেছিলেন যে, গল্পটা ঈসা তাঁদের বিরুদ্ধে বলেছেন। কিন্তু তাঁরা লোকদের ভয়ে ঈসাকে ছেড়ে চলে গেলেন।"},{"heading":"খাজনা দেবার বিষয়ে","v":13,"ve":13,"vl":"13","bn":"পরে সেই ধর্ম-নেতারা ঈসাকে তাঁর কথার ফাঁদে ধরবার জন্য কয়েকজন ফরীশী ও হেরোদীয়কে পাঠিয়ে দিলেন।"},{"v":14,"ve":14,"vl":"14","bn":"তাঁরা ঈসার কাছে এসে বললেন, “হুজুর, আমরা জানি আপনি একজন সৎ লোক। লোকে কি মনে করবে না করবে, তাতে আপনার কিছু যায় আসে না, কারণ আপনি কারও মুখ চেয়ে কিছু করেন না। আপনি সত্যভাবে আল্লাহ্‌র পথের বিষয়ে শিক্ষা দিয়ে থাকেন। এখন আপনি বলুন, মূসার শরীয়ত অনুসারে রোম-সম্রাটকে কি খাজনা দেওয়া উচিত?"},{"v":15,"ve":15,"vl":"15","bn":"আমরা তাঁকে খাজনা দেব কি দেব না?” ঈসা তাঁদের ভণ্ডামি বুঝতে পেরে বললেন, “আপনারা কেন আমাকে পরীক্ষা করছেন? আমাকে একটা দীনার এনে দেখান।”"},{"v":16,"ve":16,"vl":"16","bn":"তাঁরা একটা দীনার আনলে পর ঈসা তাঁদের জিজ্ঞাসা করলেন, “এর উপরে এই ছবি ও নাম কার?” তাঁরা বললেন, “রোম-সম্রাটের।”"},{"v":17,"ve":17,"vl":"17","bn":"ঈসা তাঁদের বললেন, “যা সম্রাটের তা সম্রাটকে দিন, আর যা আল্লাহ্‌র তা আল্লাহ্‌কে দিন।” ঈসার এই কথায় তাঁরা আশ্চর্য হয়ে গেলেন।"},{"heading":"জীবিত হয়ে উঠবার বিষয়ে","v":18,"ve":18,"vl":"18","bn":"কয়েকজন সদ্দূকী ঈসার কাছে আসলেন। সদ্দূকীদের মতে মৃতদের জীবিত হয়ে ওঠা বলে কিছু নেই। এইজন্য তাঁরা তাঁকে জিজ্ঞাসা করলেন,"},{"v":19,"ve":19,"vl":"19","bn":"“হুজুর, মূসা আমাদের জন্য এই কথা লিখে গেছেন, ‘যদি কোন লোকের ভাই সন্তানহীন অবস্থায় স্ত্রী রেখে মারা যায় তবে সেই লোক তার ভাইয়ের স্ত্রীকে বিয়ে করবে এবং ভাইয়ের হয়ে তার বংশ রক্ষা করবে।’"},{"v":20,"ve":20,"vl":"20","bn":"খুব ভাল, তারা সাত ভাই ছিল। প্রথমজন বিয়ে করে সন্তানহীন অবস্থায় মারা গেল।"},{"v":21,"ve":21,"vl":"21","bn":"তখন দ্বিতীয়জন ভাইয়ের বিধবা স্ত্রীকে বিয়ে করল, কিন্তু সেও সন্তানহীন অবস্থায় মারা গেল। তৃতীয়জনের অবস্থাও তা-ই হল।"},{"v":22,"ve":22,"vl":"22","bn":"এইভাবে সাতজনের কারও ছেলেমেয়ে হল না। শেষে সেই স্ত্রীলোকটিও মারা গেল।"},{"v":23,"ve":23,"vl":"23","bn":"তাহলে মৃত লোকেরা যখন জীবিত হয়ে উঠবে তখন সে কার স্ত্রী হবে? কারণ সাতজনের প্রত্যেকেই তো তাকে বিয়ে করেছিল।”"},{"v":24,"ve":24,"vl":"24","bn":"জবাবে ঈসা বললেন, “আপনারা ভুল করছেন, কারণ আপনারা কিতাবও জানেন না এবং আল্লাহ্‌র শক্তির বিষয়েও জানেন না।"},{"v":25,"ve":25,"vl":"25","bn":"মৃত লোকেরা যখন জীবিত হয়ে উঠবে তখন তারা বিয়েও করবে না এবং তাদের বিয়ে দেওয়াও হবে না; তারা তখন ফেরেশতাদের মত হবে।"},{"v":26,"ve":26,"vl":"26","bn":"মৃতদের জীবিত হয়ে উঠবার বিষয়ে নবী মূসার কিতাবে লেখা জ্বলন্ত ঝোপের কথা কি আপনারা পড়েন নি যে, আল্লাহ্‌ তাঁকে বললেন, ‘আমি ইব্রাহিমের আল্লাহ্‌, ইসহাকের আল্লাহ্‌ ও ইয়াকুবের আল্লাহ্‌’?"},{"v":27,"ve":27,"vl":"27","bn":"আল্লাহ্‌ তো মৃতদের আল্লাহ্‌ নন, তিনি জীবিতদেরই আল্লাহ্‌। আপনারা খুব ভুল করছেন।”"},{"heading":"সবচেয়ে বড় হুকুম","v":28,"ve":28,"vl":"28","bn":"একজন আলেম সেখানে এসে তাঁদের তর্কাতর্কি শুনলেন। ঈসা যে তাঁদের উপযুক্ত জবাব দিয়েছেন তা লক্ষ্য করে তিনি তাঁকে জিজ্ঞাসা করলেন, “তৌরাত শরীফের মধ্যে সবচেয়ে দরকারী হুকুম কোন্‌টা?”"},{"v":29,"ve":29,"vl":"29","bn":"জবাবে ঈসা বললেন, “সবচেয়ে দরকারী হুকুম হল, ‘বনি-ইসরাইলরা, শোন, আমাদের মাবুদ আল্লাহ্‌ এক।"},{"v":30,"ve":30,"vl":"30","bn":"তোমরা প্রত্যেকে তোমাদের সমস্ত দিল, সমস্ত প্রাণ, সমস্ত মন এবং সমস্ত শক্তি দিয়ে তোমাদের মাবুদ আল্লাহ্‌কে মহব্বত করবে।’"},{"v":31,"ve":31,"vl":"31","bn":"তার পরের দরকারী হুকুম হল এই, ‘তোমার প্রতিবেশীকে নিজের মত মহব্বত করবে।’ এই দু’টা হুকুমের চেয়ে বড় হুকুম আর কিছুই নেই।”"},{"v":32,"ve":32,"vl":"32","bn":"তখন সেই আলেম বললেন, “হুজুর, খুব ভাল কথা। আপনি সত্যি কথাই বলেছেন যে, আল্লাহ্‌ এক এবং তিনি ছাড়া আর কোন মাবুদ নেই।"},{"v":33,"ve":33,"vl":"33","bn":"আর সমস্ত দিল, সমস্ত বুদ্ধি ও সমস্ত শক্তি দিয়ে তাঁকে মহব্বত করা এবং প্রতিবেশীকে নিজের মত মহব্বত করা পশু ও অন্য সব কোরবানীর চেয়ে অনেক বেশী দরকারী।”"},{"v":34,"ve":34,"vl":"34","bn":"ঈসা যখন দেখলেন সেই আলেমটি খুব বুদ্ধিমানের মত জবাব দিয়েছেন তখন তিনি তাঁকে বললেন, “আল্লাহ্‌র রাজ্য থেকে আপনি বেশী দূরে নন।” সেই সময় থেকে ঈসাকে আর কোন প্রশ্ন জিজ্ঞাসা করতে কারও সাহস হল না।"},{"heading":"আলেমদের কাছে হযরত ঈসার প্রশ্ন","v":35,"ve":35,"vl":"35","bn":"ঈসা বায়তুল-মোকাদ্দসে শিক্ষা দেবার সময় জিজ্ঞাসা করলেন, “আলেমেরা কেমন করে বলেন মসীহ্‌ দাউদের বংশধর?"},{"v":36,"ve":36,"vl":"36","bn":"দাউদ তো পাক-রূহের পরিচালনায় বলেছেন, ‘মাবুদ আমার প্রভুকে বললেন, যতক্ষণ না আমি তোমার শত্রুদের তোমার পায়ের তলায় রাখি, ততক্ষণ তুমি আমার ডান দিকে বস।’"},{"v":37,"ve":37,"vl":"37","bn":"দাউদ নিজেই তো তাঁকে প্রভু বলেছেন, তবে কেমন করে মসীহ্‌ তাঁর বংশধর হতে পারেন?” অনেক লোক খুশী মনে ঈসার কথা শুনছিল।"},{"v":38,"ve":38,"vl":"38","bn":"শিক্ষা দিতে দিতে ঈসা বললেন, “আলেমদের সম্বন্ধে সাবধান হও। তাঁরা লম্বা লম্বা জুব্বা পরে বেড়াতে এবং হাটে-বাজারে সম্মান পেতে চান।"},{"v":39,"ve":39,"vl":"39","bn":"তাঁরা মজলিস-খানায় প্রধান প্রধান আসনে ও মেজবানীর সময়ে সম্মানের জায়গায় বসতে চান।"},{"v":40,"ve":40,"vl":"40","bn":"এক দিকে তাঁরা লোককে দেখাবার জন্য লম্বা লম্বা মুনাজাত করেন, অন্য দিকে বিধবাদের সম্পত্তি দখল করেন। এই লোকদের অনেক বেশী আজাব হবে।”"},{"heading":"গরীব বিধবার দান","v":41,"ve":41,"vl":"41","bn":"এর পর ঈসা বায়তুল-মোকাদ্দসের দান্তবাক্সের কাছে বসে লোকদের টাকা-পয়সা দান করা লক্ষ্য করছিলেন। অনেক ধনী লোক অনেক টাকা-পয়সা দিল।"},{"v":42,"ve":42,"vl":"42","bn":"পরে একজন গরীব বিধবা এসে মাত্র দু’টা পয়সা রাখল।"},{"v":43,"ve":43,"vl":"43","bn":"তখন ঈসা তাঁর সাহাবীদের ডেকে বললেন, “আমি তোমাদের সত্যিই বলছি, এই গরীব বিধবা অন্য সবার চেয়ে অনেক বেশী এই দান্তবাক্সে রাখল।"},{"v":44,"ve":44,"vl":"44","bn":"সেই লোকেরা তাদের প্রচুর ধন থেকে দান করেছে, কিন্তু এই স্ত্রীলোকটির অভাব থাকলেও বেঁচে থাকবার জন্য তার যা ছিল সমস্তই দিয়ে দিল।”"}],"13":[{"heading":"কেয়ামতের আলামত","v":1,"ve":1,"vl":"1","bn":"ঈসা বায়তুল-মোকাদ্দস থেকে যখন বের হয়ে যাচ্ছিলেন তখন তাঁর একজন সাহাবী তাঁকে বললেন, “হুজুর, দেখুন, কত বড় বড় পাথর, আর কি সুন্দর সুন্দর দালান!”"},{"v":2,"ve":2,"vl":"2","bn":"ঈসা তাঁকে বললেন, “তুমি তো এই সব বড় বড় দালান দেখছ, কিন্তু এর একটা পাথরও আর একটা পাথরের উপরে থাকবে না; সমস্তই ভেংগে ফেলা হবে।”"},{"v":3,"ve":3,"vl":"3","bn":"পরে ঈসা যখন বায়তুল-মোকাদ্দসের উল্টাদিকে জৈতুন পাহাড়ের উপরে বসে ছিলেন তখন পিতর, ইয়াকুব, ইউহোন্না ও আন্দ্রিয় তাঁকে গোপনে জিজ্ঞাসা করলেন,"},{"v":4,"ve":4,"vl":"4","bn":"“আপনি আমাদের বলুন, কখন এই সব হবে? কোন্‌ চিহ্ন দেখে আমরা বুঝতে পারব এই সব পূর্ণ হবার সময়ে এসেছে?”"},{"v":5,"ve":5,"vl":"5","bn":"ঈসা তাঁদের বললেন, “দেখো, কেউ যেন তোমাদের না ঠকায়।"},{"v":6,"ve":6,"vl":"6","bn":"অনেকেই আমার নাম নিয়ে এসে বলবে, ‘আমিই সেই’ এবং অনেককে ঠকাবে।"},{"v":7,"ve":7,"vl":"7","bn":"যখন তোমরা যুদ্ধের আওয়াজ ও যুদ্ধের খবরাখবর শুনবে তখন ভয় পেয়ো না। এই সব হবেই, কিন্তু তখনও শেষ নয়।"},{"v":8,"ve":8,"vl":"8","bn":"এক জাতি অন্য জাতির বিরুদ্ধে, এক রাজ্য অন্য রাজ্যের বিরুদ্ধে যুদ্ধ করবে। অনেক জায়গায় ভূমিকমপ ও দুর্ভিক্ষ হবে। কিন্তু এই সব কেবল যন্ত্রণার শুরু।"},{"v":9,"ve":9,"vl":"9","bn":"“তোমরা সতর্ক থেকো। লোকে তোমাদের বিচার-সভার লোকদের হাতে ধরিয়ে দেবে এবং মজলিস-খানায় বেত মারবে। আমার জন্য দেশের শাসনকর্তা ও বাদশাহ্‌দের সামনে তোমাদের দাঁড়াতে হবে। তাঁদের সামনে আমার বিষয়ে তোমাদের সাক্ষ্য দিতে হবে।"},{"v":10,"ve":10,"vl":"10","bn":"সমস্ত জাতির কাছে প্রথমে আল্লাহ্‌র দেওয়া সুসংবাদ তবলিগ করতে হবে।"},{"v":11,"ve":11,"vl":"11","bn":"যখন তোমাদের ধরে বিচারের জন্য নিয়ে যাবে তখন কি বলতে হবে তা আগে থেকে চিন্তা কোরো না। সেই সময়ে যে কথা তোমাদের বলে দেওয়া হবে তোমরা তা-ই বলবে, কারণ তোমরাই যে বলবে তা নয় বরং পাক-রূহ্‌ই কথা বলবেন।"},{"v":12,"ve":12,"vl":"12","bn":"“ভাই ভাইকে, পিতা ছেলেকে মেরে ফেলবার জন্য ধরিয়ে দেবে। ছেলেমেয়েরা মা-বাবার বিরুদ্ধে দাঁড়িয়ে তাদের খুন করাবে।"},{"v":13,"ve":13,"vl":"13","bn":"আমার জন্য সবাই তোমাদের ঘৃণা করবে, কিন্তু যে শেষ পর্যন্ত স্থির থাকবে সে উদ্ধার পাবে।"},{"v":14,"ve":14,"vl":"14","bn":"“সর্বনাশা ঘৃণার জিনিস যেখানে থাকা উচিত নয়, তোমরা যখন তা সেখানে থাকতে দেখবে- যে পড়ে সে বুঝুক- তখন যারা এহুদিয়াতে থাকবে তারা পাহাড়ী এলাকায় পালিয়ে যাক।"},{"v":15,"ve":15,"vl":"15","bn":"যে ছাদের উপরে থাকবে সে কিছু নেবার জন্য নীচে নেমে ঘরে না ঢুকুক।"},{"v":16,"ve":16,"vl":"16","bn":"যে ক্ষেতের মধ্যে থাকবে সে গায়ের চাদর নেওয়ার জন্য না ফিরুক।"},{"v":17,"ve":17,"vl":"17","bn":"তখন যারা গর্ভবতী আর যারা সন্তানকে বুকের দুধ খাওয়ায় তাদের অবস্থা কি ভীষণই না হবে!"},{"v":18,"ve":18,"vl":"18","bn":"মুনাজাত কর যেন এই সমস্ত শীতকালে না হয়,"},{"v":19,"ve":19,"vl":"19","bn":"কারণ সেই সময় এমন কষ্ট হবে যা দুনিয়ার সৃষ্টি থেকে এই পর্যন্ত হয় নি এবং তার পরেও আর হবে না।"},{"v":20,"ve":20,"vl":"20","bn":"মাবুদ যদি সেই দিনগুলো কমিয়ে না দিতেন তবে কেউই বাঁচত না। কিন্তু তাঁর বাছাই করা বান্দাদের জন্য সেই দিনগুলো আল্লাহ্‌ কমিয়ে দিয়েছেন।"},{"v":21,"ve":21,"vl":"21","bn":"সেই সময় যদি কেউ তোমাদের বলে, ‘দেখ, মসীহ্‌ এখানে,’ বা ‘দেখ, মসীহ্‌ ওখানে,’ তোমরা বিশ্বাস কোরো না;"},{"v":22,"ve":22,"vl":"22","bn":"কারণ ভণ্ড মসীহেরা ও ভণ্ড নবীরা আসবে এবং চিহ্ন ও কুদরতি দেখাবে, যেন আল্লাহ্‌র বাছাই করা বান্দাদের সম্ভব হলে ঠকাতে পারে।"},{"v":23,"ve":23,"vl":"23","bn":"তোমরা কিন্তু সতর্ক থেকো। আমি তোমাদের আগেই সব কিছু বলে রাখলাম।"},{"v":24,"ve":24,"vl":"24","bn":"“সেই সময়ের কষ্টের ঠিক পরেই সূর্য অন্ধকার হয়ে যাবে, চাঁদ আর আলো দেবে না,"},{"v":25,"ve":25,"vl":"25","bn":"তারাগুলো আসমান থেকে খসে পড়ে যাবে এবং চাঁদ-সূর্য-তারা আর স্থির থাকবে না।"},{"v":26,"ve":26,"vl":"26","bn":"সেই সময়ে লোকেরা ইব্‌ন্তেআদমকে মহাশক্তি ও মহিমার সংগে মেঘের মধ্যে দুনিয়াতে আসতে দেখবে।"},{"v":27,"ve":27,"vl":"27","bn":"তিনি তাঁর ফেরেশতাদের পাঠিয়ে দুনিয়ার এক সীমা থেকে অন্য সীমা পর্যন্ত চারদিক থেকে আল্লাহ্‌র সব বাছাই করা বান্দা জমায়েত করবেন।"},{"v":28,"ve":28,"vl":"28","bn":"“ডুমুর গাছ দেখে শিক্ষা লাভ কর। যখন তার ডালপালা নরম হয়ে তাতে পাতা বের হয় তখন তোমরা জানতে পার যে, গরমকাল এসেছে।"},{"v":29,"ve":29,"vl":"29","bn":"সেইভাবে যখন তোমরা দেখবে এই সব ঘটছে তখন বুঝতে পারবে যে, ইব্‌ন্তেআদম কাছে এসে গেছেন, এমন কি, দরজায় উপস্থিত।"},{"v":30,"ve":30,"vl":"30","bn":"আমি তোমাদের সত্যিই বলছি, যখন এই সব হবে তখনও এই কালের কিছু লোক বেঁচে থাকবে।"},{"v":31,"ve":31,"vl":"31","bn":"আসমান ও জমীন শেষ হয়ে যাবে কিন্তু আমার কথা চিরদিন থাকবে।"},{"heading":"হযরত ঈসা মসীহ্‌ কখন আসবেন?","v":32,"ve":32,"vl":"32","bn":"“সেই দিন ও সেই সময়ের কথা কেউই জানে না- বেহেশতের ফেরেশতারাও না, পুত্রও না, কেবল পিতাই জানেন।"},{"v":33,"ve":33,"vl":"33","bn":"তোমরা সাবধান হও, সতর্ক থাক ও মুনাজাত কর, কারণ সেই দিন কখন আসবে তা তোমরা জান না।"},{"v":34,"ve":34,"vl":"34","bn":"সেই দিনটা আসবে এমন একজন লোকের মত করে যিনি বিদেশে যাচ্ছেন। বাড়ী ছেড়ে যাবার আগে তিনি গোলামদের হাতে সব দায়িত্ব দিলেন। তিনি প্রত্যেক গোলামকে তার কাজ দিলেন এবং দারোয়ানকে জেগে থাকতে বললেন।"},{"v":35,"ve":35,"vl":"35","bn":"“তোমরাও এইভাবে জেগে থাক, কারণ বাড়ীর কর্তা সন্ধ্যায়, কি দুপুর রাতে, কি ভোর রাতে, কি সকালে আসবেন তা তোমরা জান না।"},{"v":36,"ve":36,"vl":"36","bn":"হঠাৎ তিনি এসে যেন না দেখেন তোমরা ঘুমিয়ে রয়েছ।"},{"v":37,"ve":37,"vl":"37","bn":"তোমাদের যা বলছি তা সবাইকে বলি, জেগে থাক।”"}],"14":[{"heading":"হযরত ঈসার মাথায় আতর ঢালা","v":1,"ve":1,"vl":"1","bn":"উদ্ধার-ঈদ ও খামিহীন রুটির ঈদের তখন মাত্র আর দু’দিন বাকী। প্রধান ইমামেরা ও আলেমেরা গোপনে ঈসাকে ধরে হত্যা করবার উপায় খুঁজছিলেন।"},{"v":2,"ve":2,"vl":"2","bn":"তাঁরা বললেন, “ঈদের সময়ে নয়; লোকদের মধ্যে গোলমাল হতে পারে।”"},{"v":3,"ve":3,"vl":"3","bn":"ঈসা তখন বেথানিয়াতে চর্মরোগী শিমোনের বাড়ীতে ছিলেন। তিনি যখন খাচ্ছিলেন তখন একজন স্ত্রীলোক একটা সাদা পাথরের পাত্রে করে খুব দামী ও খাঁটি আতর আনল। পাত্রটা ভেংগে সে ঈসার মাথায় সেই আতর ঢেলে দিল।"},{"v":4,"ve":4,"vl":"4","bn":"সেখানে যাঁরা উপস্থিত ছিলেন তাঁদের মধ্যে কয়েকজন বিরক্ত হয়ে একে অন্যকে বলতে লাগলেন, “এইভাবে আতরটা নষ্ট করা হল কেন?"},{"v":5,"ve":5,"vl":"5","bn":"এটা বিক্রি করলে তো তিনশো দীনারেরও বেশী হত এবং তা গরীবদের দেওয়া যেত।” এই বলে তাঁরা স্ত্রীলোকটিকে বকাবকি করতে লাগলেন।"},{"v":6,"ve":6,"vl":"6","bn":"তখন ঈসা বললেন, “থাম, কেন তোমরা ওকে দুঃখ দিচ্ছ? ও তো আমার জন্য ভাল কাজই করেছে।"},{"v":7,"ve":7,"vl":"7","bn":"গরীবেরা সব সময় তোমাদের মধ্যে আছে, আর যখন ইচ্ছা তখনই তোমরা তাদের সাহায্য করতে পার, কিন্তু আমাকে তোমরা সব সময় পাবে না।"},{"v":8,"ve":8,"vl":"8","bn":"ও যা পেরেছে তা করেছে। আমাকে কবরের জন্য প্রস্তুত করতে ও আগেই আমার গায়ের উপর আতর ঢেলে দিয়েছে।"},{"v":9,"ve":9,"vl":"9","bn":"আমি তোমাদের সত্যি বলছি, দুনিয়ার যে কোন জায়গায় আল্লাহ্‌র দেওয়া সুসংবাদ তবলিগ করা হবে, সেখানে এই স্ত্রীলোকটির কথা মনে করিয়ে দেবার জন্য ওর এই কাজের কথাও বলা হবে।”"},{"v":10,"ve":10,"vl":"10","bn":"এর পর এহুদা ইষ্কারিয়োৎ নামে সেই বারোজন সাহাবীদের মধ্যে একজন ঈসাকে ধরিয়ে দেবার জন্য প্রধান ইমামদের কাছে গেল।"},{"v":11,"ve":11,"vl":"11","bn":"ইমামেরা এহুদার কথা শুনে খুশী হলেন এবং তাকে টাকা দেবেন বলে কথা দিলেন। তখন এহুদা ঈসাকে ধরিয়ে দেবার জন্য সুযোগ খুঁজতে লাগল।"},{"heading":"সাহাবীদের সংগে হযরত ঈসা মসীহের শেষ মেজবানী","v":12,"ve":12,"vl":"12","bn":"খামিহীন রুটির ঈদের প্রথম দিনে উদ্ধার-ঈদের মেজবানীর জন্য ভেড়ার বাচ্চা জবাই করা হত। তাই সাহাবীরা ঈসাকে জিজ্ঞাসা করলেন, “আপনার জন্য উদ্ধার-ঈদের মেজবানী কোথায় গিয়ে আমাদের প্রস্তুত করতে বলেন?”"},{"v":13,"ve":13,"vl":"13","bn":"তখন ঈসা তাঁর দু’জন সাহাবীকে এই বলে পাঠিয়ে দিলেন, “তোমরা শহরে যাও। সেখানে এমন একজন পুরুষ লোকের দেখা পাবে, যে একটা কলসীতে করে পানি নিয়ে যাচ্ছে। তোমরা তার পিছনে পিছনে যেয়ো।"},{"v":14,"ve":14,"vl":"14","bn":"সে যে বাড়ীতে ঢুকবে সেই বাড়ীর কর্তাকে বোলো, ‘ওস্তাদ বলছেন, সাহাবীদের সংগে যেখানে আমি উদ্ধার-ঈদের মেজবানী খেতে পারি আমার সেই মেহমান্তখানাটা কোথায়?’"},{"v":15,"ve":15,"vl":"15","bn":"এতে সে তোমাদের উপরতলার একটা সাজানো বড় ঘর দেখিয়ে দেবে। সব কিছু সেখানেই প্রস্তুত কোরো।”"},{"v":16,"ve":16,"vl":"16","bn":"তখন সাহাবীরা গিয়ে শহরে ঢুকলেন, আর ঈসা যেমন বলেছিলেন সব কিছু তেমনই দেখতে পেলেন এবং উদ্ধার-ঈদের মেজবানী প্রস্তুত করলেন।"},{"v":17,"ve":17,"vl":"17","bn":"সন্ধ্যা হলে পর ঈসা সেই বারোজনকে নিয়ে সেখানে গেলেন।"},{"v":18,"ve":18,"vl":"18","bn":"তাঁরা যখন বসে খাচ্ছিলেন তখন ঈসা বললেন, “আমি তোমাদের সত্যি বলছি, তোমাদের মধ্যে একজন আমাকে ধরিয়ে দেবে, আর সে আমার সংগে খাচ্ছে।”"},{"v":19,"ve":19,"vl":"19","bn":"সাহাবীরা দুঃখিত হলেন এবং একজনের পরে আর একজন বলতে লাগলেন, “সে কি আমি, হুজুর?”"},{"v":20,"ve":20,"vl":"20","bn":"ঈসা তাঁদের বললেন, “সে এই বারোজনের মধ্যে একজন, যে আমার সংগে পাত্রের মধ্যে রুটি ডুবাচ্ছে।"},{"v":21,"ve":21,"vl":"21","bn":"ইব্‌ন্তেআদমের মৃত্যুর বিষয়ে পাক-কিতাবে যা লেখা আছে তিনি সেভাবেই মারা যাবেন বটে, কিন্তু হায় সেই লোক, যে তাঁকে ধরিয়ে দেয়! সেই লোকের জন্ম না হলেই বরং তার পক্ষে ভাল হত।”"},{"v":22,"ve":22,"vl":"22","bn":"খাওয়া-দাওয়া চলছে, এমন সময় ঈসা রুটি নিয়ে আল্লাহ্‌কে শুকরিয়া জানালেন এবং তা টুকরা টুকরা করে সাহাবীদের হাতে দিয়ে বললেন, “এই নাও, এটা আমার শরীর।”"},{"v":23,"ve":23,"vl":"23","bn":"তারপর তিনি পেয়ালা নিয়ে আল্লাহ্‌কে শুকরিয়া জানালেন এবং সাহাবীদের দিলেন। তাঁরা সবাই সেই পেয়ালা থেকে খেলেন।"},{"v":24,"ve":24,"vl":"24","bn":"তখন ঈসা তাঁদের বললেন, “এ আমার রক্ত যা অনেকের জন্য দেওয়া হবে। মানুষের জন্য আল্লাহ্‌র নতুন ব্যবস্থা আমার এই রক্তের দ্বারাই বহাল করা হবে।"},{"v":25,"ve":25,"vl":"25","bn":"তোমাদের সত্যি বলছি, যতদিন আমি আল্লাহ্‌র রাজ্যে আংগুর ফলের রস আবার নতুন ভাবে না খাই ততদিন পর্যন্ত আর আমি তা খাব না।”"},{"v":26,"ve":26,"vl":"26","bn":"এর পরে তাঁরা একটা কাওয়ালী গেয়ে বের হয়ে জৈতুন পাহাড়ে গেলেন।"},{"heading":"হযরত পিতরের অস্বীকার করবার কথা","v":27,"ve":27,"vl":"27","bn":"ঈসা তাঁর সাহাবীদের বললেন, “আমাকে নিয়ে তোমাদের সকলের মনে বাধা আসবে। পাক-কিতাবে লেখা আছে, ‘আমি পালককে মেরে ফেলব, তাতে মেষগুলো ছড়িয়ে পড়বে।’"},{"v":28,"ve":28,"vl":"28","bn":"তবে আমাকে মৃত্যু থেকে জীবিত করা হলে পর আমি তোমাদের আগেই গালীলে যাব।”"},{"v":29,"ve":29,"vl":"29","bn":"তখন পিতর বললেন, “সবার মনে বাধা আসলেও আমার মনে বাধা আসবে না।”"},{"v":30,"ve":30,"vl":"30","bn":"ঈসা তাঁকে বললেন, “আমি তোমাকে সত্যিই বলছি, আজ ভোর রাতে মোরগ দু’বার ডাকবার আগেই তুমি তিন বার বলবে যে, তুমি আমাকে চেনো না।”"},{"v":31,"ve":31,"vl":"31","bn":"কিন্তু পিতর আরও জোর দিয়ে বললেন, “যদি আমাকে আপনার সংগে মরতেও হয় তবুও আমি কখনও বলব না যে, আমি আপনাকে চিনি না।” সাহাবীরা সবাই সেই একই কথা বললেন।"},{"heading":"গেৎশিমানী বাগানে হযরত ঈসা মসীহ্‌","v":32,"ve":32,"vl":"32","bn":"এর পরে ঈসা ও তাঁর সাহাবীরা গেৎশিমানী নামে একটা জায়গায় গেলেন। সেখানে ঈসা তাঁর সাহাবীদের বললেন, “আমি যতক্ষণ মুনাজাত করি ততক্ষণ তোমরা এখানে বসে থাক।”"},{"v":33,"ve":33,"vl":"33","bn":"এই বলে তিনি পিতর, ইয়াকুব ও ইউহোন্নাকে নিজের সংগে নিলেন এবং মনে খুব ব্যথা ও কষ্ট পেতে লাগলেন।"},{"v":34,"ve":34,"vl":"34","bn":"তিনি তাঁদের বললেন, “দুঃখে যেন আমার প্রাণ বেরিয়ে যাচ্ছে। তোমরা এখানে জেগে থাক।”"},{"v":35,"ve":35,"vl":"35","bn":"তার পরে তিনি কিছু দূরে গিয়ে মাটিতে উবুড় হয়ে পড়ে মুনাজাত করলেন যেন সম্ভব হলে এই দুঃখের সময়টা তাঁর কাছ থেকে দূর হয়।"},{"v":36,"ve":36,"vl":"36","bn":"তিনি বললেন, “আব্বা, পিতা, তোমার কাছে তো সবই সম্ভব। এই দুঃখের পেয়ালা আমার কাছ থেকে তুমি নিয়ে যাও। তবুও আমার ইচ্ছামত না হোক, কিন্তু তোমার ইচ্ছামত হোক।”"},{"v":37,"ve":37,"vl":"37","bn":"এর পরে তিনি সাহাবীদের কাছে ফিরে এসে দেখলেন তঁাঁরা ঘুমিয়ে পড়েছেন। তিনি পিতরকে বললেন, “শিমোন, তুমি ঘুমা\"ছ? এক ঘণ্টাও কি জেগে থাকতে পার নি?"},{"v":38,"ve":38,"vl":"38","bn":"জেগে থাক ও মুনাজাত কর যেন পরীক্ষায় না পড়। অন্তরের ইচ্ছা আছে বটে, কিন্তু শরীর দুর্বল।”"},{"v":39,"ve":39,"vl":"39","bn":"পরে ঈসা আবার গিয়ে সেই একই মুনাজাত করলেন।"},{"v":40,"ve":40,"vl":"40","bn":"ফিরে এসে তিনি দেখলেন আবার তাঁরা ঘুমিয়ে পড়েছেন, কারণ তাঁদের চোখ ঘুমে ভারী হয়ে গিয়েছিল। সাহাবীরা ঈসাকে কি জবাব দেবেন বুঝলেন না।"},{"v":41,"ve":41,"vl":"41","bn":"তৃতীয় বার ফিরে এসে তিনি তাঁদের বললেন, “এখনও তোমরা ঘুমা\"ছ আর বিশ্রাম করছ? যথেষ্ট হয়েছে। সময় এসে পড়েছে। দেখ, ইব্‌ন্তেআদমকে এখন গুনাহ্‌গারদের হাতে ধরিয়ে দেওয়া হচ্ছে।"},{"v":42,"ve":42,"vl":"42","bn":"ওঠো, চল আমরা যাই। যে আমাকে শত্রুদের হাতে ধরিয়ে দেবে সে এসে পড়েছে।”"},{"heading":"শত্রুদের হাতে হযরত ঈসা মসীহ্‌","v":43,"ve":43,"vl":"43","bn":"ঈসা তখনও কথা বলছেন, এমন সময় এহুদা সেখানে আসল। সে সেই বারোজন সাহাবীদের মধ্যে একজন ছিল। তার সংগে অনেক লোক ছোরা ও লাঠি নিয়ে আসল। প্রধান ইমামেরা, আলেমেরা ও বৃদ্ধ নেতারা এই লোকদের পাঠিয়েছিলেন।"},{"v":44,"ve":44,"vl":"44","bn":"ঈসাকে যে ধরিয়ে দিয়েছিল সে ঐ লোকদের সংগে একটা চিহ্ন ঠিক করেছিল। সে বলেছিল, “যাকে আমি চুমু দেব, সে-ই সেই লোক। তোমরা তাকেই ধোরো এবং পাহারা দিয়ে নিয়ে যেয়ো।”"},{"v":45,"ve":45,"vl":"45","bn":"তাই এহুদা সোজা ঈসার কাছে গিয়ে বলল, “হুজুর!” এই কথা বলেই সে তাঁকে চুমু দিল।"},{"v":46,"ve":46,"vl":"46","bn":"তখন সেই লোকেরা ঈসাকে ধরল।"},{"v":47,"ve":47,"vl":"47","bn":"যাঁরা ঈসার কাছে দাঁড়িয়ে ছিলেন তাঁদের মধ্যে একজন তাঁর ছোরা বের করলেন এবং মহা-ইমামের গোলামকে আঘাত করে তার একটা কান কেটে ফেললেন।"},{"v":48,"ve":48,"vl":"48","bn":"ঈসা সেই লোকদের বললেন, “আমি কি ডাকাত যে, আপনারা ছোরা ও লাঠি নিয়ে আমাকে ধরতে এসেছেন?"},{"v":49,"ve":49,"vl":"49","bn":"আমি তো প্রত্যেক দিনই আপনাদের মধ্যে থেকে বায়তুল-মোকাদ্দসে শিক্ষা দিতাম, কিন্তু তখন তো আপনারা আমাকে ধরেন নি। অবশ্য কিতাবের কথা পূর্ণ হতে হবে।”"},{"v":50,"ve":50,"vl":"50","bn":"সেই সময় সাহাবীরা সবাই তাঁকে ছেড়ে পালিয়ে গেলেন।"},{"v":51,"ve":51,"vl":"51","bn":"একজন যুবক কেবল একটা চাদর পরে ঈসার পিছনে পিছনে যাচ্ছিল।"},{"v":52,"ve":52,"vl":"52","bn":"লোকেরা যখন তাকে ধরল তখন সে চাদরখানা ছেড়ে দিয়ে উলংগ অবস্থায় পালিয়ে গেল।"},{"heading":"মহাসভার সামনে হযরত ঈসা মসীহ্‌","v":53,"ve":53,"vl":"53","bn":"সেই লোকেরা ঈসাকে নিয়ে মহা-ইমামের কাছে গেল। সেখানে প্রধান ইমামেরা, বৃদ্ধ নেতারা ও আলেমেরা একসংগে জমায়েত হলেন।"},{"v":54,"ve":54,"vl":"54","bn":"পিতর দূরে দূরে থেকে ঈসার পিছনে যেতে যেতে মহা-ইমামের উঠানে গিয়ে ঢুকলেন। সেখানে রক্ষীদের সংগে বসে তিনি আগুন পোহাতে লাগলেন।"},{"v":55,"ve":55,"vl":"55","bn":"প্রধান ইমামেরা এবং মহাসভার সমস্ত লোকেরা ঈসাকে হত্যা করবার জন্য তাঁর বিরুদ্ধে সাক্ষ্যের খোঁজ করছিলেন, কিন্তু কোন সাক্ষ্যই তাঁরা পেলেন না।"},{"v":56,"ve":56,"vl":"56","bn":"ঈসার বিরুদ্ধে অনেকেই মিথ্যা সাক্ষ্য দিয়েছিল কিন্তু তাদের সাক্ষ্য মিলল না।"},{"v":57,"ve":57,"vl":"57","bn":"তখন কয়েকজন উঠে তাঁর বিরুদ্ধে এই মিথ্যা সাক্ষ্য দিল,"},{"v":58,"ve":58,"vl":"58","bn":"“আমরা ওকে বলতে শুনেছি, ‘মানুষের তৈরী এই এবাদত-খানা আমি ভেংগে ফেলব এবং তিন দিনের মধ্যে এমন একটা এবাদত-খানা তৈরী করব যা মানুষের তৈরী নয়।’ ”"},{"v":59,"ve":59,"vl":"59","bn":"কিন্তু তবুও তাদের সাক্ষ্য মিলল না।"},{"v":60,"ve":60,"vl":"60","bn":"তখন মহা-ইমাম সকলের সামনে দাঁড়িয়ে ঈসাকে জিজ্ঞাসা করলেন, “তুমি কি কোন জবাবই দেবে না? তোমার বিরুদ্ধে এই লোকেরা এই সব কি সাক্ষ্য দিচ্ছে?”"},{"v":61,"ve":61,"vl":"61","bn":"ঈসা কিন্তু জবাব না দিয়ে চুপ করেই রইলেন। মহা-ইমাম আবার তাঁকে জিজ্ঞাসা করলেন, “তুমি কি গৌরবময় আল্লাহ্‌র পুত্র মসীহ্‌?”"},{"v":62,"ve":62,"vl":"62","bn":"ঈসা বললেন, “আমিই সেই। আপনারা সর্বশক্তিমান আল্লাহ্‌র ডান দিকে ইব্‌ন্তেআদমকে বসে থাকতে দেখবেন এবং আসমানের মেঘের সংগে আসতে দেখবেন।”"},{"v":63,"ve":63,"vl":"63","bn":"এতে মহা-ইমাম তাঁর কাপড় ছিঁড়ে বললেন, “আর সাক্ষীর আমাদের কি দরকার?"},{"v":64,"ve":64,"vl":"64","bn":"আপনারা তো শুনলেনই যে, ও কুফরী করল। আপনারা কি মনে করেন?” তাঁরা সবাই ঈসাকে মৃত্যুর শাস্তি পাবার উপযুক্ত বলে স্থির করলেন।"},{"v":65,"ve":65,"vl":"65","bn":"তখন কয়েকজন তাঁর গায়ে থুথু দিলেন এবং তাঁর মুখ ঢেকে তাঁকে ঘুষি মেরে বললেন, “তুই না নবী? কিছু বল্‌ দেখি!” তারপর রক্ষীরা তাঁকে নিয়ে গিয়ে চড় মারতে লাগল।"},{"heading":"হযরত পিতরের অস্বীকার","v":66,"ve":66,"vl":"66","bn":"পিতর যখন নীচে উঠানে ছিলেন তখন মহা-ইমামের একজন চাকরাণী সেখানে আসল।"},{"v":67,"ve":67,"vl":"67","bn":"সে পিতরকে আগুন পোহাতে দেখল এবং ভাল করে তাঁর দিকে তাকিয়ে দেখে বলল, “আপনিও তো ঐ নাসরতের ঈসার সংগে ছিলেন।”"},{"v":68,"ve":68,"vl":"68","bn":"পিতর কিন্তু অস্বীকার করে বললেন, “তুমি কি বলছ তা আমি জানিও না, বুঝিও না।” এই বলে পিতর বাইরের দরজার কাছে গেলেন, আর তখনই একটা মোরগ ডেকে উঠল।"},{"v":69,"ve":69,"vl":"69","bn":"চাকরাণীটা পিতরকে সেখানে দেখে যারা সেখানে দাঁড়িয়ে ছিল তাদের আবার বলল, “এই লোকটি ওদের একজন।”"},{"v":70,"ve":70,"vl":"70","bn":"পিতর আবার অস্বীকার করলেন। যারা কাছে দাঁড়িয়ে ছিল তারাও কিছুক্ষণ পর পিতরকে বলল, “নিশ্চয়ই তুমি ওদের একজন, কারণ তুমি তো গালীলের লোক।”"},{"v":71,"ve":71,"vl":"71","bn":"পিতর তখন নিজেকে বদদোয়া দিলেন এবং কসম খেয়ে বললেন, “তোমরা যার সম্বন্ধে বলছ তাকে আমি চিনি না।”"},{"v":72,"ve":72,"vl":"72","bn":"আর তখনই দ্বিতীয় বার মোরগ ডেকে উঠল। ঈসা যে বলেছিলেন, “মোরগ দু’বার ডাকবার আগেই তুমি তিন বার বলবে যে, তুমি আমাকে চেনো না,” সেই কথা তখন পিতরের মনে পড়ল। তাতে তিনি কান্নায় ভেংগে পড়লেন।"}],"15":[{"heading":"পীলাতের সামনে হযরত ঈসা মসীহ্‌","v":1,"ve":1,"vl":"1","bn":"প্রধান ইমামেরা খুব ভোরে বৃদ্ধ নেতাদের, আলেমদের ও মহাসভার সমস্ত লোকদের সংগে একটা পরামর্শ করলেন। তারপর তাঁরা ঈসাকে বেঁধে নিয়ে গিয়ে তাঁকে রোমীয় প্রধান শাসনকর্তা পীলাতের হাতে দিলেন।"},{"v":2,"ve":2,"vl":"2","bn":"তখন পীলাত ঈসাকে জিজ্ঞাসা করলেন, “তুমি কি ইহুদীদের বাদশাহ্‌?” ঈসা জবাব দিলেন, “আপনি ঠিক কথাই বলছেন।”"},{"v":3,"ve":3,"vl":"3","bn":"প্রধান ইমামেরা তাঁর নামে অনেক দোষ দিলেন।"},{"v":4,"ve":4,"vl":"4","bn":"এতে পীলাত আবার ঈসাকে জিজ্ঞাসা করলেন, “তুমি কি জবাব দেবে না? দেখ, তারা তোমাকে কত দোষ দিচ্ছে।”"},{"v":5,"ve":5,"vl":"5","bn":"ঈসা কিন্তু আর কোন জবাবই দিলেন না। এতে পীলাত আশ্চর্য হলেন।"},{"v":6,"ve":6,"vl":"6","bn":"উদ্ধার-ঈদের সময়ে লোকেরা যে কয়েদীকে চাইত পীলাত তাকে ছেড়ে দিতেন।"},{"v":7,"ve":7,"vl":"7","bn":"সেই সময় বারাব্বা নামে একজন লোক জেলখানায় বন্দী ছিল। বিদ্রোহের সময় সে বিদ্রোহীদের সংগে থেকে খুন করেছিল।"},{"v":8,"ve":8,"vl":"8","bn":"লোকেরা পীলাতের কাছে এসে বলল, “আপনি সব সময় যা করে থাকেন এখন তা-ই করুন।”"},{"v":9,"ve":9,"vl":"9","bn":"পীলাত তাদের বললেন, “তোমরা কি চাও যে, আমি ইহুদীদের বাদশাহ্‌কে ছেড়ে দিই?”"},{"v":10,"ve":10,"vl":"10","bn":"প্রধান ইমামেরা যে হিংসা করেই ঈসাকে তাঁর হাতে দিয়েছেন পীলাত তা জানতেন।"},{"v":11,"ve":11,"vl":"11","bn":"কিন্তু প্রধান ইমামেরা লোকদের উস্‌কিয়েছিলেন যেন তারা ঈসার বদলে বারাব্বাকে চেয়ে নেয়।"},{"v":12,"ve":12,"vl":"12","bn":"পীলাত আবার লোকদের জিজ্ঞাসা করলেন, “তাহলে তোমরা যাকে ইহুদীদের বাদশাহ্‌ বল তাকে নিয়ে আমি কি করব?”"},{"v":13,"ve":13,"vl":"13","bn":"লোকেরা চেঁচিয়ে বলল, “ওকে ক্রুশে দিন।”"},{"v":14,"ve":14,"vl":"14","bn":"পীলাত বললেন, “কেন, সে কি দোষ করেছে?” কিন্তু লোকেরা আরও জোরে চেঁচিয়ে বলতে লাগল, “ওকে ক্রুশে দিন।”"},{"v":15,"ve":15,"vl":"15","bn":"তখন পীলাত লোকদের সন্তুষ্ট করবার জন্য বারাব্বাকে তাদের কাছে ছেড়ে দিলেন, আর ঈসাকে ভীষণভাবে চাবুক মারবার হুকুম দিয়ে ক্রুশের উপরে হত্যা করবার জন্য দিলেন।"},{"heading":"সৈন্যদের ঠাট্টা-তামাশা","v":16,"ve":16,"vl":"16","bn":"তারপর সৈন্যেরা ঈসাকে নিয়ে প্রধান শাসনকর্তার বাড়ীর ভিতরে গেল। সেখানে তারা অন্য সব সৈন্যদের একত্র করল।"},{"v":17,"ve":17,"vl":"17","bn":"তারা ঈসাকে বেগুনে কাপড় পরাল, আর কাঁটা-লতা দিয়ে একটা তাজ গেঁথে তাঁর মাথায় পরিয়ে দিল।"},{"v":18,"ve":18,"vl":"18","bn":"তার পরে তারা ঈসাকে বলতে লাগল, “ইহুদী-রাজ, মারহাবা!”"},{"v":19,"ve":19,"vl":"19","bn":"তারা একটা লাঠি দিয়ে ঈসার মাথায় বারবার মারতে লাগল এবং তাঁর গায়ে থুথু দিল, আর হাঁটু পেতে তাঁকে সম্মান দেখাবার ভান করল।"},{"v":20,"ve":20,"vl":"20","bn":"এইভাবে তাঁকে ঠাট্টা-তামাশা করবার পর তারা সেই বেগুনে কাপড় খুলে নিয়ে তাঁকে তাঁর নিজের কাপড় পরিয়ে দিল এবং ক্রুশের উপরে হত্যা করবার জন্য নিয়ে চলল।"},{"heading":"ক্রুশের উপরে হযরত ঈসা মসীহ্‌","v":21,"ve":21,"vl":"21","bn":"সেই সময় শিমোন নামে কূরীণী শহরের একজন লোক গ্রামের দিক থেকে এসে সেই পথে যাচ্ছিলেন। ইনি ছিলেন আলেকজাণ্ডার ও রূফের পিতা। সৈন্যেরা তাঁকে ঈসার ক্রুশটা বয়ে নিয়ে যেতে বাধ্য করল।"},{"v":22,"ve":22,"vl":"22","bn":"তারা ঈসাকে গল্‌গথা, অর্থাৎ মাথার খুলির স্থান নামে একটা জায়গায় নিয়ে গেল।"},{"v":23,"ve":23,"vl":"23","bn":"পরে তারা ঈসাকে গন্ধরস মিশানো সিরকা খেতে দিল, কিন্তু তিনি তা খেলেন না।"},{"v":24,"ve":24,"vl":"24","bn":"এর পরে তারা ঈসাকে ক্রুশে দিল। সৈন্যেরা তাঁর কাপড়-চোপড় ভাগ করবার জন্য গুলিবাঁট করে দেখতে চাইল কার ভাগ্যে কি পড়ে।"},{"v":25,"ve":25,"vl":"25","bn":"সকাল ন’টার সময় তারা তাঁকে ক্রুশে দিয়েছিল।"},{"v":26,"ve":26,"vl":"26","bn":"ঈসার বিরুদ্ধে দোষ-নামাতে লেখা ছিল, “ইহুদীদের বাদশাহ্‌।”"},{"v":27,"ve":27,"vl":"27","bn":"তারা দু’জন ডাকাতকেও ঈসার সংগে ক্রুশে দিল, একজনকে ডান দিকে ও অন্যজনকে বাঁ দিকে।"},{"v":28,"ve":28,"vl":"28","bn":"তাতে পাক-কিতাবের এই কথা পূর্ণ হল: “তাঁকে অন্যায়কারীদের সংগে গোণা হল।”"},{"v":29,"ve":29,"vl":"29","bn":"যারা সেই পথ দিয়ে যাচ্ছিল তারা মাথা নেড়ে ঈসাকে ঠাট্টা করে বলল, “ওহে, তুমি না বায়তুল-মোকাদ্দস ভেংগে আবার তিন দিনের মধ্যে তা তৈরী করতে পার!"},{"v":30,"ve":30,"vl":"30","bn":"এখন ক্রুশ থেকে নেমে এসে নিজেকে রক্ষা কর!”"},{"v":31,"ve":31,"vl":"31","bn":"প্রধান ইমামেরা ও আলেমেরাও ঈসাকে ঠাট্টা করবার উদ্দেশ্যে নিজেদের মধ্যে বলাবলি করতে লাগলেন, “ও অন্যদের রক্ষা করত, নিজেকে রক্ষা করতে পারে না।"},{"v":32,"ve":32,"vl":"32","bn":"ঐ যে মসীহ্‌, বনি-ইসরাইলদের বাদশাহ্‌! ক্রুশ থেকে ও নেমে আসুক যেন আমরা দেখে ঈমান আনতে পারি।” ঈসার সংগে যাদের ক্রুশে দেওয়া হয়েছিল তারাও তাঁকে টিট্‌কারি দিল।"},{"heading":"হযরত ঈসা মসীহের মৃত্য","v":33,"ve":33,"vl":"33","bn":"পরে দুুপুর বারোটা থেকে বেলা তিনটা পর্যন্ত সারা দেশ অন্ধকার হয়ে রইল।"},{"v":34,"ve":34,"vl":"34","bn":"বেলা তিনটার সময় ঈসা জোরে চিৎকার করে বললেন, “এলোই, এলোই, লামা শবক্তানী,” অর্থাৎ “আল্লাহ্‌ আমার, আল্লাহ্‌ আমার, কেন তুমি আমাকে ত্যাগ করেছ?”"},{"v":35,"ve":35,"vl":"35","bn":"যারা কাছে দাঁড়িয়ে ছিল তাদের কয়েকজন এই কথা শুনে বলল, “শোন, শোন, ও নবী ইলিয়াসকে ডাকছে।”"},{"v":36,"ve":36,"vl":"36","bn":"তখন একজন লোক দৌড়ে গিয়ে একটা সপঞ্জ সিরকায় ভিজাল এবং একটা লাঠির মাথায় লাগিয়ে তা ঈসাকে খেতে দিল। সে বলল, “থাক্‌, দেখি ইলিয়াস ওকে নামিয়ে নিতে আসেন কি না।”"},{"v":37,"ve":37,"vl":"37","bn":"এর পরে ঈসা জোরে চিৎকার করে প্রাণত্যাগ করলেন।"},{"v":38,"ve":38,"vl":"38","bn":"তখন বায়তুল-মোকাদ্দসের পর্দাটা উপর থেকে নীচ পর্যন্ত চিরে দু’ভাগ হয়ে গেল।"},{"v":39,"ve":39,"vl":"39","bn":"যে সেনাপতি ঈসার সামনে দাঁড়িয়ে ছিল সে ঈসাকে এইভাবে মারা যেতে দেখে বলল, “সত্যিই ইনি ইব্‌নুল্লাহ্‌ ছিলেন।”"},{"v":40,"ve":40,"vl":"40","bn":"কয়েকজন স্ত্রীলোক দূরে দাঁড়িয়ে এই সব দেখছিলেন। তাঁদের মধ্যে ছিলেন মগ্‌দলীনী মরিয়ম, দুই ইয়াকুবের মধ্যে ছোট ইয়াকুব ও ইউসুফের মা মরিয়ম আর শালোমী।"},{"v":41,"ve":41,"vl":"41","bn":"ঈসা যখন গালীলে ছিলেন তখন এই স্ত্রীলোকেরা তাঁর সংগে সব জায়গায় যেতেন এবং তাঁর সেবা করতেন। আরও অনেক স্ত্রীলোক, যাঁরা তাঁর সংগে সংগে জেরুজালেমে এসেছিলেন, তাঁরাও সেখানে ছিলেন।"},{"heading":"হযরত ঈসা মসীহের কবর","v":42,"ve":42,"vl":"42","bn":"সেই দিনটা ছিল আয়োজনের দিন, অর্থাৎ বিশ্রামবারের আগের দিন।"},{"v":43,"ve":43,"vl":"43","bn":"যখন সন্ধ্যা হয়ে আসল তখন অরিমাথিয়া গ্রামের ইউসুফ সাহস করে পীলাতের কাছে গিয়ে ঈসার লাশটি চাইলেন। তিনি মহাসভার একজন নাম-করা সদস্য ছিলেন এবং তিনি নিজে আল্লাহ্‌র রাজ্যের জন্য অপেক্ষা করছিলেন।"},{"v":44,"ve":44,"vl":"44","bn":"পীলাত আশ্চর্য হলেন যে, ঈসা এত তাড়াতাড়ি মারা গেছেন। সত্যি সত্যি ঈসার মৃত্যু হয়েছে কি না, তা সেনাপতিকে ডেকে তিনি জিজ্ঞাসা করলেন।"},{"v":45,"ve":45,"vl":"45","bn":"যখন সেনাপতির কাছ থেকে তিনি জানতে পারলেন যে, সত্যিই তাঁর মৃত্যু হয়েছে তখন লাশটি ইউসুফকে দিলেন।"},{"v":46,"ve":46,"vl":"46","bn":"ইউসুফ গিয়ে কাপড় কিনে আনলেন এবং ঈসার লাশটি নামিয়ে সেই কাপড়ে জড়ালেন, আর পাহাড় কেটে তৈরী করা একটা কবরে সেই লাশটি রাখলেন। তারপর তিনি কবরের মুখে একটা পাথর গড়িয়ে দিলেন।"},{"v":47,"ve":47,"vl":"47","bn":"ঈসার লাশটি কোথায় রাখা হল তা মগ্‌দলীনী মরিয়ম ও ইউসুফের মা মরিয়ম দেখলেন।"}],"16":[{"heading":"মৃত্যুর উপরে জয়লাভ","v":1,"ve":1,"vl":"1","bn":"বিশ্রামবার পার হয়ে গেলে পর মগ্‌দলীনী মরিয়ম, ইয়াকুবের মা মরিয়ম এবং শালোমী ঈসার লাশে মাখাবার জন্য খোশবু মলম কিনে আনলেন।"},{"v":2,"ve":2,"vl":"2","bn":"সপ্তার প্রথম দিনের খুব সকালে, সূর্য উঠবার সংগে সংগেই তাঁরা কবরের কাছে গেলেন।"},{"v":3,"ve":3,"vl":"3","bn":"সেই সময় তাঁরা একে অন্যকে জিজ্ঞাসা করছিলেন, “কবরের মুখ থেকে কে ঐ পাথরটা সরিয়ে দেবে?”"},{"v":4,"ve":4,"vl":"4","bn":"কিন্তু তাঁরা চেয়ে দেখলেন যে, পাথরখানা সরানো হয়েছে। সেই পাথরটা খুব বড় ছিল।"},{"v":5,"ve":5,"vl":"5","bn":"কবরের গুহায় ঢুকে তাঁরা দেখলেন, সাদা কাপড়-পরা একজন যুবক ডান দিকে বসে আছেন। এতে তাঁরা খুব অবাক হলেন।"},{"v":6,"ve":6,"vl":"6","bn":"সেই যুবকটি বললেন, “অবাক হয়ো না। নাসরত গ্রামের ঈসা, যাঁকে ক্রুশের উপরে হত্যা করা হয়েছিল, তাঁকেই তোমরা খুঁজছো তো? তিনি এখানে নেই, তিনি জীবিত হয়ে উঠেছেন। যেখানে তারা তাঁকে রেখেছিল সেই জায়গা দেখ।"},{"v":7,"ve":7,"vl":"7","bn":"তারপর তোমরা গিয়ে তাঁর সাহাবীদের ও পিতরকে এই কথা বল যে, তিনি তাদের আগে গালীলে যাচ্ছেন। তিনি যেমন বলেছিলেন তেমনই তারা তাঁকে সেখানে দেখতে পাবে।”"},{"v":8,"ve":8,"vl":"8","bn":"সেই স্ত্রীলোকেরা কিছু বুঝতে না পেরে কাঁপতে কাঁপতে কবরের গুহা থেকে বের হয়ে আসলেন এবং সেখান থেকে দৌড়ে পালিয়ে গেলেন। তাঁরা এত ভয় পেয়েছিলেন যে, কাউকে কিছু বললেন না।"},{"heading":"সাহাবীদের সংগে হযরত ঈসার সাক্ষাৎ","v":9,"ve":9,"vl":"9","bn":"সপ্তার প্রথম দিনের ভোর বেলায় ঈসা মৃত্যু থেকে জীবিত হয়ে উঠলেন। পরে তিনি মগ্‌দলীনী মরিয়মকে প্রথমে দেখা দিলেন। এই মরিয়মের ভিতর থেকে ঈসা সাতটা ভূত ছাড়িয়েছিলেন।"},{"v":10,"ve":10,"vl":"10","bn":"তাঁকে দেখবার পর মরিয়ম গিয়ে যাঁরা ঈসার সংগে থাকতেন তাঁদের কাছে খবর দিলেন। সেই সময় তাঁরা মনের দুঃখে কাঁদছিলেন।"},{"v":11,"ve":11,"vl":"11","bn":"ঈসা জীবিত হয়েছেন ও মরিয়ম তাঁকে দেখেছেন, এই কথা শুনে তাঁরা বিশ্বাস করলেন না।"},{"v":12,"ve":12,"vl":"12","bn":"এর পরে তাঁর দু’জন সাহাবী যখন হেঁটে গ্রামের দিক যাচ্ছিলেন তখন ঈসা অন্য রকম চেহারায় তাঁদের দেখা দিলেন।"},{"v":13,"ve":13,"vl":"13","bn":"তাঁরা ফিরে গিয়ে বাকী সবাইকে সেই খবর দিলেন, কিন্তু তাঁদের কথাও অন্য সাহাবীরা বিশ্বাস করলেন না।"},{"v":14,"ve":14,"vl":"14","bn":"এর পরে ঈসা তাঁর এগারোজন সাহাবীকে দেখা দিলেন। তখন তাঁরা খাচ্ছিলেন। বিশ্বাসের অভাব ও অন্তরের কঠিনতার জন্য তিনি তাঁদের বকলেন, কারণ তিনি মৃত্যু থেকে জীবিত হয়ে উঠবার পরে যাঁরা তাঁকে দেখেছিলেন তাঁদের কথা তাঁরা বিশ্বাস করেন নি।"},{"v":15,"ve":15,"vl":"15","bn":"ঈসা সেই সাহাবীদের বললেন, “তোমরা দুনিয়ার সব জায়গায় যাও এবং সব লোকদের কাছে আল্লাহ্‌র দেওয়া সুসংবাদ তবলিগ কর।"},{"v":16,"ve":16,"vl":"16","bn":"যে কেউ ঈমান আনে এবং তরিকাবন্দী নেয় সে-ই নাজাত পাবে; কিন্তু যে ঈমান আনে না আল্লাহ্‌ তাঁকে দোষী বলে স্থির করে শাস্তি দেবেন।"},{"v":17,"ve":17,"vl":"17","bn":"যারা ঈমান আনে তাদের মধ্যে এই চিহ্নগুলো দেখা যাবে- আমার নামে তারা ভূত ছাড়াবে, তারা নতুন নতুন ভাষায় কথা বলবে,"},{"v":18,"ve":18,"vl":"18","bn":"তারা হাতে করে সাপ তুলে ধরবে, যদি তারা ভীষণ বিষাক্ত কিছু খায় তবে তাদের কোন ক্ষতি হবে না, আর তারা রোগীদের গায়ে হাত দিলে রোগীরা ভাল হবে।”"},{"heading":"হযরত ঈসার বেহেশতে ফিরে যাওয়া","v":19,"ve":19,"vl":"19","bn":"সাহাবীদের কাছে এই সব কথা বলবার পরে হযরত ঈসাকে বেহেশতে তুলে নেওয়া হল। সেখানে তিনি আল্লাহ্‌র ডান দিকে বসলেন।"},{"v":20,"ve":20,"vl":"20","bn":"পরে সাহাবীরা গিয়ে সব জায়গায় তবলিগ করতে লাগলেন। হযরত ঈসা তাঁদের মধ্য দিয়ে তাঁদের সংগে কাজ করতে থাকলেন এবং তাঁদের অলৌকিক কাজ করবার শক্তি দিয়ে প্রমাণ করলেন যে, তাঁরা যা তবলিগ করছেন তা সত্যি। ॥ভব"}]}};
